const $=id=>document.getElementById(id);
// V6.1 LOCAL-FIRST: frontend workspace ID seçmir. Biznes datasının master nüsxəsi brauzer IndexedDB-dədir; server yalnız müvəqqəti sessiya workspace-i işlədir.
const workspaceId='local-first-session';
function migrateTaxDataBrowserKeys(){try{const aliases={deviceId:'taxdata.deviceId',task:'taxdata_agent_etx_task',tin:'taxdata_agent_etx_tin'};for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(!k||Object.values(aliases).includes(k))continue;let target='';if(k.endsWith('.deviceId'))target=aliases.deviceId;else if(k.endsWith('_agent_etx_task'))target=aliases.task;else if(k.endsWith('_agent_etx_tin'))target=aliases.tin;if(target){if(!localStorage.getItem(target))localStorage.setItem(target,localStorage.getItem(k)||'');localStorage.removeItem(k)}}}catch{}}
migrateTaxDataBrowserKeys();
const deviceId=(()=>{let x=localStorage.getItem('taxdata.deviceId');if(!x){x='dev_'+(crypto.randomUUID?.()||Math.random().toString(36).slice(2)+Date.now())+'_'+Array.from(crypto.getRandomValues(new Uint8Array(12))).map(b=>b.toString(16).padStart(2,'0')).join('');localStorage.setItem('taxdata.deviceId',x)}return x})();
let currentUser=null,whatsappUrl='';
let sectionAccessState={sections:[],allowedSections:[],pendingCount:0};
let adminSectionUser=null;
const state={companyUploadId:null,companies:[],invoices:[],selected:new Set(),outgoingInvoices:[],outgoingSelected:new Set(),contracts:[],documentArchives:[],documentArchiveFolder:'',activeTemplates:{},templateMappings:{},printCopies:{hf:1,tt:2,qr:2},lastResult:null,editor:{type:null,entity:null,uploadId:null,mapping:{},originalMapping:{},fields:{},originalCells:new Map(),selectedCell:null,selectedField:null,rows:[],dirty:false}};
const toast=m=>{const t=$('toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3800)};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=n=>Number(n||0).toLocaleString('az-AZ',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₼';
const num=n=>Number(n||0).toLocaleString('az-AZ',{maximumFractionDigits:4});
const normalize=s=>String(s||'').toLowerCase().replace(/[ə]/g,'e').replace(/[ı]/g,'i').replace(/[ö]/g,'o').replace(/[ü]/g,'u').replace(/[ş]/g,'s').replace(/[ç]/g,'c').replace(/[ğ]/g,'g').replace(/[^a-z0-9]/g,'');
const cleanNote=s=>String(s||'').replace(/[\u00a0\u202f]/g,' ').trim().replace(/^(?:\s*qeyd(?:lər)?\s*[:;,\.\-–—]*\s*)+/iu,'').trim();
const entityFromVoen=(voen,fallback='LEGAL')=>{const d=String(voen||'').replace(/\D/g,'');if(d.endsWith('2'))return'INDIVIDUAL';if(d.endsWith('1'))return'LEGAL';return fallback};
const entityLabel=e=>e==='INDIVIDUAL'?'Fiziki şəxs':'Hüquqi şəxs';
const activeKey=(entity,type)=>`${entity}.${type}`;
let localSyncTimer=null,localSyncRunning=false,localSyncAgain=false,localSyncPromise=null,lastLocalSyncError='';
let cloudSyncTimer=null,cloudSyncRunning=false,cloudLastAt=0,lastCloudSyncError='';
function isWorkspaceMutation(url,opt={}){const m=String(opt.method||'GET').toUpperCase();if(!['POST','PUT','PATCH','DELETE'].includes(m))return false;const u=String(url||'');if(u.startsWith('/api/auth/')||u.startsWith('/api/admin/')||u.startsWith('/api/local-workspace/')||u.startsWith('/api/etaxes-export/'))return false;if(/\/(open-folder|open-file|open-word)(?:[/?]|$)/.test(u))return false;return true}
function scheduleCloudSnapshot(reason='auto'){if(!currentUser?.id)return;clearTimeout(cloudSyncTimer);const elapsed=Date.now()-cloudLastAt,delay=Math.max(12000,5*60*1000-elapsed);cloudSyncTimer=setTimeout(()=>flushCloudSnapshot(reason,false).catch(e=>console.warn(e)),delay)}
async function flushCloudSnapshot(reason='auto',forceNewVersion=false){if(!currentUser?.id||cloudSyncRunning)return null;clearTimeout(cloudSyncTimer);cloudSyncTimer=null;cloudSyncRunning=true;try{const d=await LocalWorkspaceStore.cloudBackup(reason,forceNewVersion);cloudLastAt=Date.now();lastCloudSyncError='';await refreshCloudStorageInfo(d);return d}catch(e){lastCloudSyncError=e.message||String(e);await refreshCloudStorageInfo();throw e}finally{cloudSyncRunning=false}}
function scheduleLocalSnapshot(reason='dəyişiklik'){if(!currentUser?.id)return;localSyncAgain=true;clearTimeout(localSyncTimer);localSyncTimer=setTimeout(()=>flushLocalSnapshot(reason).catch(e=>console.warn(e)),650)}
async function flushLocalSnapshot(reason='auto'){if(!currentUser?.id)return null;clearTimeout(localSyncTimer);localSyncTimer=null;if(localSyncPromise){localSyncAgain=true;try{await localSyncPromise}catch{}if(localSyncAgain){localSyncAgain=false;return flushLocalSnapshot(reason)}return null}localSyncRunning=true;localSyncAgain=false;localSyncPromise=(async()=>{try{setLocalStorageStatus('Yerli backup yenilənir...','busy');const rec=await LocalWorkspaceStore.snapshot(currentUser,{writeFolder:true,reason});lastLocalSyncError='';await refreshLocalStorageInfo(rec);scheduleCloudSnapshot(reason);return rec}catch(e){lastLocalSyncError=e.message||String(e);setLocalStorageStatus('Yerli backup xətası: '+lastLocalSyncError,'error');throw e}finally{localSyncRunning=false}})();try{return await localSyncPromise}finally{localSyncPromise=null;if(localSyncAgain){localSyncAgain=false;localSyncTimer=setTimeout(()=>flushLocalSnapshot('ardıcıl dəyişiklik').catch(()=>{}),250)}}}
const api=async(url,opt={},_retried=false)=>{const headers=new Headers(opt.headers||{});const r=await fetch(url,{...opt,headers,credentials:'same-origin'});let d;try{d=await r.json()}catch{d=null}if(!r.ok){if(r.status===401)showAuthScreen('Sessiya bitib. Yenidən giriş edin.');if(r.status===428&&d?.code==='LOCAL_WORKSPACE_REQUIRED'&&!_retried&&currentUser){await prepareLocalWorkspace(currentUser);return api(url,opt,true)}if(r.status===403&&d?.code==='SECTION_ACCESS_REQUIRED'){refreshMySectionAccess().catch(()=>{});setTimeout(()=>openSectionAccessModal(false),0)}const e=new Error(d?.error||d?.message||`HTTP ${r.status}`);e.code=d?.code||'';e.sectionKey=d?.sectionKey||'';throw e}if(isWorkspaceMutation(url,opt))scheduleLocalSnapshot(url);return d};
const downloadWithWorkspace=async(url,filename,_retried=false)=>{const r=await fetch(url,{credentials:'same-origin'});if(!r.ok){let d;try{d=await r.json()}catch{}if(r.status===401)showAuthScreen('Sessiya bitib.');if(r.status===428&&d?.code==='LOCAL_WORKSPACE_REQUIRED'&&!_retried&&currentUser){await prepareLocalWorkspace(currentUser);return downloadWithWorkspace(url,filename,true)}if(r.status===403&&d?.code==='SECTION_ACCESS_REQUIRED'){await refreshMySectionAccess().catch(()=>{});openSectionAccessModal(false)}throw new Error(d?.error||`HTTP ${r.status}`)}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename||'download';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)};

function authStatus(id,msg,kind=''){const e=$(id);if(!e)return;e.textContent=msg||'';e.className='auth-status '+kind}
let accessCountdownTimer=null,accessSyncTimer=null,accessExpiryHandled=false;
function stopAccessCountdown(){if(accessCountdownTimer){clearInterval(accessCountdownTimer);accessCountdownTimer=null}if(accessSyncTimer){clearInterval(accessSyncTimer);accessSyncTimer=null}}
function formatRemaining(ms){const sec=Math.max(0,Math.floor(ms/1000)),days=Math.floor(sec/86400),hours=Math.floor((sec%86400)/3600),mins=Math.floor((sec%3600)/60),secs=sec%60;return `${days?days+' gün ':''}${String(hours).padStart(2,'0')}:${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}`}
function updateAccessCountdown(){const box=$('accessCountdown'),txt=$('accessCountdownText');if(!box||!txt||!currentUser)return;box.classList.remove('warning','expired','unlimited');if(currentUser.role==='ADMIN'){txt.textContent='Admin · limitsiz';box.classList.add('unlimited');box.title='Admin hesabında istifadə müddəti məhdudiyyəti yoxdur.';return}const end=currentUser.accessEndAt?new Date(currentUser.accessEndAt):null;if(!end||Number.isNaN(end.getTime())){txt.textContent='Müddət: limitsiz';box.classList.add('unlimited');box.title='Bu hesab üçün bitmə vaxtı təyin edilməyib.';return}const ms=end.getTime()-Date.now();box.title=`Giriş bitmə vaxtı: ${end.toLocaleString('az-AZ')}`;if(ms<=0){txt.textContent='İstifadə müddəti bitdi';box.classList.add('expired');if(!accessExpiryHandled){accessExpiryHandled=true;stopAccessCountdown();setTimeout(async()=>{try{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'})}catch{}showAuthScreen('İstifadə müddətiniz bitib. Adminlə əlaqə saxlayın.')},300)}return}txt.textContent=`Qalan vaxt: ${formatRemaining(ms)}`;if(ms<24*3600*1000)box.classList.add('warning')}
function hasSectionAccess(key){return currentUser?.role==='ADMIN'||(sectionAccessState.allowedSections||[]).includes(key)}
function applySectionAccessState(data){sectionAccessState=data&&Array.isArray(data.sections)?data:{sections:[],allowedSections:[],pendingCount:0};window.taxDataApplySectionAccess?.();renderSectionAccessList()}
async function refreshMySectionAccess(){if(!currentUser)return null;const d=await api('/api/auth/section-access');applySectionAccessState(d);return d}
function renderSectionAccessList(){const box=$('sectionAccessList');if(!box)return;const rows=sectionAccessState.sections||[];if(!rows.length){box.innerHTML='<div class="permission-empty">Bölmə siyahısı yüklənir...</div>';return}box.innerHTML=rows.map(x=>{const allowed=!!x.allowed,status=String(x.requestStatus||'');let badge=allowed?'<span class="permission-badge allowed">İcazə verilib</span>':status==='PENDING'?'<span class="permission-badge pending">Admin təsdiqi gözləyir</span>':status==='REJECTED'?'<span class="permission-badge rejected">Əvvəlki istək rədd edilib</span>':'<span class="permission-badge locked">Bağlıdır</span>';let action=allowed?'':status==='PENDING'?'<button class="mini ghost" disabled>İstək göndərilib</button>':`<button class="mini success request-section-access" data-key="${esc(x.key)}">İcazə istə</button>`;return `<div class="permission-row"><div><b>${esc(x.label)}</b><small>${allowed?'Bu bölmə əsas menyuda görünür və istifadə edilə bilər.':'Bu bölmə əsas menyuda gizlidir və server girişinə bağlıdır.'}</small></div><div class="permission-row-actions">${badge}${action}</div></div>`}).join('');box.querySelectorAll('.request-section-access').forEach(b=>b.onclick=()=>requestSectionAccess(b.dataset.key))}
async function openSectionAccessModal(refresh=true){if(currentUser?.role==='ADMIN')return toast('Admin bütün bölmələrə avtomatik girişə malikdir.');$('sectionAccessModal')?.classList.remove('hidden');if(refresh)try{await refreshMySectionAccess()}catch(e){toast(e.message)}else renderSectionAccessList()}
async function requestSectionAccess(sectionKey){try{const d=await api('/api/auth/section-access/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sectionKey})});toast(d.message||'İcazə istəyi göndərildi.');await refreshMySectionAccess()}catch(e){toast(e.message)}}
async function refreshAccessState(){if(!currentUser)return;try{const r=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});if(r.status===401){showAuthScreen('Sessiya və ya istifadə müddəti bitib. Yenidən giriş edin.');return}if(!r.ok)return;const d=await r.json();if(d?.user){const before=JSON.stringify([currentUser.etaxesPhone||'',currentUser.etaxesUserId||'',currentUser.etaxesTin||'',currentUser.profileUpdatedAt||'']);currentUser={...currentUser,...d.user};const after=JSON.stringify([currentUser.etaxesPhone||'',currentUser.etaxesUserId||'',currentUser.etaxesTin||'',currentUser.profileUpdatedAt||'']);if(d.sectionAccess)applySectionAccessState(d.sectionAccess);if(before!==after){applyEtaxesProfile();LocalWorkspaceStore.syncUserProfile(currentUser).catch(e=>console.warn('Profile local sync:',e));toast('Admin e‑Taxes profil məlumatlarını yenilədi. Yeni məlumatlar tətbiq olundu.')}updateAccessCountdown()}}catch{/* Müvəqqəti şəbəkə xətası istifadəçini sistemdən çıxarmır. */}}
function startAccessCountdown(){stopAccessCountdown();accessExpiryHandled=false;updateAccessCountdown();accessCountdownTimer=setInterval(updateAccessCountdown,1000);accessSyncTimer=setInterval(refreshAccessState,10000)}
function showAuthScreen(msg=''){stopAccessCountdown();stopAgentUiMonitoring();currentUser=null;sectionAccessState={sections:[],allowedSections:[],pendingCount:0};$('appShell').classList.add('hidden');$('authScreen').classList.remove('hidden');if(msg)authStatus('loginStatus',msg,'error')}
function showApp(user,access=null){currentUser=user;resetAgentUiForLogin();if(access)applySectionAccessState(access);$('authScreen').classList.add('hidden');$('appShell').classList.remove('hidden');$('accountName').textContent=`${user.username}${user.whatsapp?' · '+user.whatsapp:''}`;$('workspaceBadge').textContent=`V7.1.14 · ${user.role==='ADMIN'?'Admin':'Production'}`;$('workspaceBadge').title='Şirkət rekvizitləri SQL bazasında saxlanılır; qaimə və digər workspace məlumatları local-first iş axınında qalır.';$('adminPanelBtn').classList.toggle('hidden',user.role!=='ADMIN');$('sectionAccessBtn')?.classList.toggle('hidden',user.role==='ADMIN');if($('sideAdminBtn'))$('sideAdminBtn').classList.toggle('hidden',user.role!=='ADMIN');applyEtaxesProfile();LocalWorkspaceStore.syncUserProfile(user).catch(e=>console.warn('Profile local sync:',e));window.taxDataApplySectionAccess?.();startAccessCountdown()}
function applyEtaxesProfile(){if(!currentUser)return;const defs=[['etxPhone','etaxesPhone','ASAN İmza telefon nömrəsi'],['etxUserId','etaxesUserId','ASAN İmza İstifadəçi ID'],['etxTin','etaxesTin','VÖEN']];for(const [elId,key,label] of defs){const e=$(elId);if(!e)continue;const value=String(currentUser[key]||'').replace(/\D/g,'');const locked=currentUser.role!=='ADMIN'&&!!value;if(value)e.value=value;e.readOnly=locked;e.title=locked?`${label} hesab profilində saxlanılıb. Dəyişiklik yalnız admin paneldən edilir.`:''}}
async function authRequest(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)});let d={};try{d=await r.json()}catch{}if(!r.ok){const e=new Error(d.error||`HTTP ${r.status}`);e.code=d.code||'';throw e}return d}
function openWhatsApp(){if(!whatsappUrl)return toast('Admin əlaqə linki konfiqurasiya edilməyib.');const user=$('regUsername')?.value||$('loginUsername')?.value||'';const wa=$('regWhatsapp')?.value||'';const text=encodeURIComponent(`Salam. E-Qaimə sisteminə giriş icazəsi almaq istəyirəm.${user?' Username: '+user:''}${wa?' WhatsApp: '+wa:''}`);window.open(`${whatsappUrl}${whatsappUrl.includes('?')?'&':'?'}text=${text}`,'_blank','noopener')}
function setLocalStorageStatus(msg,kind=''){const e=$('localStorageStatus');if(!e)return;e.textContent=msg||'';e.className='status '+(kind||'')}
async function refreshCloudStorageInfo(prefetched=null){const e=$('cloudStorageStatus');if(!e||!currentUser?.id)return;try{const d=prefetched?.backup?{enabled:true,retentionDays:3,hasBackup:true,latest:prefetched.backup}:await LocalWorkspaceStore.cloudStatus();if(!d.enabled){e.textContent='Cloud disaster-recovery bu mühitdə aktiv deyil.';e.className='status local-storage-strip';return}const b=d.latest;if(!b){e.textContent=`Supabase PostgreSQL: aktiv · ${d.retentionDays||3} gün saxlanma · hələ backup yoxdur${lastCloudSyncError?' · '+lastCloudSyncError:''}`;e.className='status local-storage-strip '+(lastCloudSyncError?'error':'');return}const when=new Date(b.updatedAt||b.createdAt).toLocaleString('az-AZ'),exp=new Date(b.expiresAt).toLocaleString('az-AZ');e.textContent=`Supabase PostgreSQL: ${LocalWorkspaceStore.fmtBytes(b.zipSizeBytes||0)} · Son backup: ${when} · Silinmə: ${exp}${lastCloudSyncError?' · '+lastCloudSyncError:''}`;e.className='status local-storage-strip '+(lastCloudSyncError?'error':'ok')}catch(err){e.textContent='Cloud backup vəziyyəti oxunmadı: '+err.message;e.className='status local-storage-strip error'}}
async function refreshLocalStorageInfo(rec=null){if(!currentUser?.id)return;const info=await LocalWorkspaceStore.info(currentUser.id);const r=rec||info;const size=LocalWorkspaceStore.fmtBytes(r.bytes??info.bytes??0),when=(r.updatedAt||info.updatedAt)?new Date(r.updatedAt||info.updatedAt).toLocaleString('az-AZ'):'hələ backup yoxdur';if($('localFolderStatus'))$('localFolderStatus').textContent=info.hasFolder?(info.folderWritable?`Seçilmiş lokal qovluq: ${info.folderName} · Cari backup + son 10 versiya${info.storageQuota?` · Brauzer yaddaşı ${(100*(info.storageUsage||0)/info.storageQuota).toFixed(1)}% istifadə` : ''}`:`Seçilmiş lokal qovluq yadda saxlanılıb: ${info.folderName}. Brauzer icazəsi tələb edərsə “Backup-ı seçilən qovluğa yaz” düyməsinə bir dəfə klikləyin.`):'Lokal backup qovluğu hələ seçilməyib.';if($('chooseLocalFolder'))$('chooseLocalFolder').textContent=info.hasFolder?'Lokal backup qovluğunu dəyiş':'Lokal backup qovluğu seç';setLocalStorageStatus(`Bu kompüterdə lokal workspace: ${size} · Son backup: ${when}${lastLocalSyncError?' · '+lastLocalSyncError:''}`,lastLocalSyncError?'error':'ok');await refreshCloudStorageInfo()}
async function ensureBackupFolderRequired(user){if(!window.showDirectoryPicker)return;const info=await LocalWorkspaceStore.info(user.id);if(info.hasFolder)return;const modal=$('backupFolderRequiredModal'),status=$('backupFolderRequiredStatus'),btn=$('backupFolderRequiredChoose');if(!modal||!btn)return;modal.classList.remove('hidden');await new Promise(resolve=>{btn.onclick=async()=>{try{btn.disabled=true;status.className='status';status.textContent='Backup qovluğuna icazə yoxlanılır...';let folderName=info.folderName||'';if(info.hasFolder){try{await LocalWorkspaceStore.copyLatestBackupToFolder(user)}catch{folderName=''}}if(!folderName){status.textContent='Qovluq seçilir...';const h=await LocalWorkspaceStore.chooseDirectory(user.id);folderName=h.name;await LocalWorkspaceStore.copyLatestBackupToFolder(user)}status.textContent=`${folderName} hazırdır. İlk backup yazıldı.`;modal.classList.add('hidden');await refreshLocalStorageInfo();resolve()}catch(e){status.textContent=e.message;status.className='status error'}finally{btn.disabled=false}}})}
async function prepareLocalWorkspace(user){setLocalStorageStatus('Bu kompüterdəki lokal workspace açılır...','busy');const d=await LocalWorkspaceStore.ensureServerSession(user);await refreshLocalStorageInfo(d.record||null);if(d.source==='cloud')toast('Bu kompüterdə lokal backup tapılmadı; ən son 3 günlük cloud backup avtomatik bərpa edildi.');scheduleCloudSnapshot('login-sync');return d}
async function bootstrapAuth(){try{const pub=await fetch('/api/auth/public-info').then(r=>r.json());whatsappUrl=pub.whatsappUrl||'';$('buyAccess')?.classList.toggle('hidden',!whatsappUrl);$('buyAccess2')?.classList.toggle('hidden',!whatsappUrl);if($('registrationApprovalNote'))$('registrationApprovalNote').textContent=pub.autoApproveRegistration?'Yeni qeydiyyat avtomatik aktivdir: hesab və qeydiyyat etdiyiniz ilk cihaz dərhal giriş edə bilər. Məhsul bölmələri ayrıca admin səlahiyyəti ilə açılır; başqa cihaz yenə admin təsdiqi tələb edir.':'Qeydiyyatdan sonra hesab və qeydiyyat etdiyiniz cihaz admin tərəfindən təsdiqlənməlidir. Bölmə səlahiyyətləri ayrıca verilir. Başqa cihazdan giriş ayrıca admin təsdiqi olmadan mümkün deyil.'}catch{}try{const r=await fetch('/api/auth/me',{credentials:'same-origin'});if(!r.ok)throw new Error();const d=await r.json();showApp(d.user,d.sectionAccess);await prepareLocalWorkspace(d.user);await ensureBackupFolderRequired(d.user);await bootstrap()}catch(e){console.warn(e);showAuthScreen(e?.message||'')}}
$('showRegister').onclick=()=>{$('loginPane').classList.add('hidden');$('registerPane').classList.remove('hidden');authStatus('registerStatus','')};
$('backToLogin').onclick=()=>{$('registerPane').classList.add('hidden');$('loginPane').classList.remove('hidden')};
$('buyAccess').onclick=openWhatsApp;$('buyAccess2').onclick=openWhatsApp;
$('loginBtn').onclick=async()=>{const username=$('loginUsername').value.trim(),password=$('loginPassword').value;if(!username||!password)return authStatus('loginStatus','Username və parol yazın.','error');try{$('loginBtn').disabled=true;authStatus('loginStatus','Yoxlanılır...');const d=await authRequest('/api/auth/login',{username,password,deviceId});showApp(d.user,d.sectionAccess);authStatus('loginStatus','');await prepareLocalWorkspace(d.user);await ensureBackupFolderRequired(d.user);await bootstrap()}catch(e){authStatus('loginStatus',e.message,'error');if(['USER_PENDING','DEVICE_PENDING'].includes(e.code))setTimeout(()=>{if(confirm(e.message+' WhatsApp ilə adminə yazmaq istəyirsiniz?'))openWhatsApp()},50)}finally{$('loginBtn').disabled=false}};
$('loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')$('loginBtn').click()});
$('registerBtn').onclick=async()=>{const username=$('regUsername').value.trim(),whatsapp=$('regWhatsapp').value.trim(),etaxesPhone=$('regEtaxesPhone').value.trim(),etaxesUserId=$('regEtaxesUserId').value.trim(),etaxesTin=$('regEtaxesTin').value.replace(/\D/g,''),password=$('regPassword').value,p2=$('regPassword2').value;if(password!==p2)return authStatus('registerStatus','Parollar eyni deyil.','error');if(etaxesPhone.replace(/\D/g,'').length<9)return authStatus('registerStatus','ASAN İmza telefon nömrəsini düzgün yazın.','error');if(!/^\d{1,20}$/.test(etaxesUserId))return authStatus('registerStatus','ASAN İmza İstifadəçi ID yalnız rəqəmlərdən ibarət olmalıdır.','error');if(etaxesTin.length!==10)return authStatus('registerStatus','VÖEN 10 rəqəm olmalıdır.','error');try{$('registerBtn').disabled=true;const d=await authRequest('/api/auth/register',{username,whatsapp,etaxesPhone,etaxesUserId,etaxesTin,password,deviceId});authStatus('registerStatus',d.message+(d.autoApproved?' İndi giriş edə bilərsiniz.':' WhatsApp düyməsi ilə adminə məlumat verə bilərsiniz.'),'ok')}catch(e){authStatus('registerStatus',e.message,'error')}finally{$('registerBtn').disabled=false}};

$('sectionAccessBtn')?.addEventListener('click',()=>openSectionAccessModal());
$('closeSectionAccess')?.addEventListener('click',()=>$('sectionAccessModal')?.classList.add('hidden'));
$('sectionAccessModal')?.addEventListener('click',e=>{if(e.target===$('sectionAccessModal'))$('sectionAccessModal').classList.add('hidden')});

$('logoutBtn').onclick=async()=>{let backupSaved=true,cloudSaved=true;try{await flushLocalSnapshot('logout')}catch(e){backupSaved=false;console.warn('Logout backup:',e)}try{await flushCloudSnapshot('logout',true)}catch(e){cloudSaved=false;console.warn('Logout cloud backup:',e)}try{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'})}catch(e){console.warn('Logout request:',e)}showAuthScreen(backupSaved&&cloudSaved?'Hesabdan çıxış edildi. Lokal və 3 günlük cloud backup saxlanıldı.':'Hesabdan çıxış edildi. Backup qatlarından birində yenilənmə xətası oldu; əvvəlki nüsxələr saxlanılıb.')};
$('changePasswordBtn').onclick=()=>{if(!hasSectionAccess('07.03'))return openSectionAccessModal();$('passwordModal').classList.remove('hidden');$('oldPassword').value=$('newPassword').value=$('newPassword2').value=''};$('closePasswordModal').onclick=()=>$('passwordModal').classList.add('hidden');
$('savePassword').onclick=async()=>{const oldPassword=$('oldPassword').value,newPassword=$('newPassword').value;if(newPassword!==$('newPassword2').value)return toast('Yeni parollar eyni deyil.');try{await flushLocalSnapshot('parol dəyişməzdən əvvəl');await api('/api/auth/change-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({oldPassword,newPassword})});$('passwordModal').classList.add('hidden');showAuthScreen('Parol dəyişdirildi. Lokal backup saxlanıldı; yenidən giriş edin.')}catch(e){toast(e.message)}};

async function loadAdminUsers(){try{const [d]=await Promise.all([api('/api/admin/users'),loadAdminSectionOverview(false)]);renderAdminUsers(d.users||[])}catch(e){toast(e.message)}}
function toDateTimeLocal(v){if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return'';const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`}
function accessStatus(u){if(u.role==='ADMIN')return{label:'Limitsiz',cls:'ok'};const now=Date.now(),st=u.accessStartAt?new Date(u.accessStartAt).getTime():null,en=u.accessEndAt?new Date(u.accessEndAt).getTime():null;if(en&&en<=now)return{label:'Müddət bitib',cls:'expired'};if(st&&st>now)return{label:'Gözləyir',cls:'pending'};if(en)return{label:'Aktiv · '+formatRemaining(en-now),cls:'active'};return{label:'Limitsiz',cls:'ok'}}
function renderAdminUsers(users){
  const q=normalize($('adminUserSearch')?.value);const list=users.filter(u=>!q||[u.username,u.whatsapp,u.status,u.role,u.etaxes_phone,u.etaxes_user_id,u.etaxes_tin].some(v=>normalize(v).includes(q)));
  $('adminUsersBody').innerHTML=list.map(u=>{const devices=(u.devices||[]).map(d=>`<div class="admin-device ${(d.status||'').toLowerCase()}"><b>${esc(d.status)}</b>${d.registration_device?' · Qeydiyyat cihazı':''} · ${esc((d.device_label||'').slice(0,90))}${d.status==='PENDING'?` <button class="mini adm-device-approve" data-uid="${esc(u.id)}" data-did="${esc(d.id)}">Bu cihazı təsdiqlə</button>`:''}</div>`).join('')||'—';const st=String(u.status||'').toLowerCase();const etaxesProfile=u.role==='ADMIN'?'<span class="access-state ok">Admin · sərbəst</span>':`<div class="admin-etaxes-profile" data-id="${esc(u.id)}"><label>Telefon<input class="adm-etx-phone" inputmode="tel" value="${esc(u.etaxes_phone||'')}" placeholder="50XXXXXXX"></label><label>İstifadəçi ID<input class="adm-etx-userid" inputmode="numeric" value="${esc(u.etaxes_user_id||'')}" placeholder="ASAN ID"></label><label>VÖEN<input class="adm-etx-tin" inputmode="numeric" maxlength="10" value="${esc(u.etaxes_tin||'')}" placeholder="10 rəqəm"></label><button class="mini success adm-etaxes-save" data-id="${esc(u.id)}">Profili saxla</button></div>`;const a=accessStatus(u);const access=u.role==='ADMIN'?'<span class="access-state ok">Limitsiz</span>':`<div class="admin-access" data-id="${esc(u.id)}"><span class="access-state ${esc(a.cls)}">${esc(a.label)}</span><label>Başlanğıc<input class="adm-access-start" type="datetime-local" value="${esc(toDateTimeLocal(u.accessStartAt))}"></label><label>Bitmə<input class="adm-access-end" type="datetime-local" value="${esc(toDateTimeLocal(u.accessEndAt))}"></label><div class="admin-access-actions"><button class="mini success adm-access-save" data-id="${esc(u.id)}">Müddəti saxla</button><button class="mini ghost adm-access-quick" data-id="${esc(u.id)}" data-days="7">7 gün</button><button class="mini ghost adm-access-quick" data-id="${esc(u.id)}" data-days="30">30 gün</button><button class="mini ghost adm-access-unlimited" data-id="${esc(u.id)}">Limitsiz</button></div></div>`;const pending=Number(u.sectionAccess?.pendingCount||0);const granted=(u.sectionAccess?.allowedSections||[]).length,totalSections=(u.sectionAccess?.sections||[]).length||10;const permBtn=`<button class="mini permission-button adm-sections" data-id="${esc(u.id)}" data-user="${esc(u.username)}">🔐 Səlahiyyətlər · ${granted}/${totalSections}${pending?` <span class="request-count">${pending}</span>`:''}</button>`;const actions=u.role==='ADMIN'?'Admin hesabı · bütün bölmələr açıq':`${permBtn} ${u.status==='PENDING'?`<button class="mini success adm-approve" data-id="${esc(u.id)}">Hesab + cihazı təsdiqlə</button>`:''}${u.status==='DISABLED'?` <button class="mini adm-enable" data-id="${esc(u.id)}">Aktiv et</button>`:` <button class="mini danger adm-disable" data-id="${esc(u.id)}">Deaktiv et</button>`} <button class="mini ghost adm-reset" data-id="${esc(u.id)}">Cihazı sıfırla</button> <button class="mini danger adm-delete" data-id="${esc(u.id)}">Sil</button>`;return `<tr><td><b>${esc(u.username)}</b><br><small>${esc(u.role)}</small><br><small>ID: ${esc(u.id)}</small></td><td>${u.whatsapp?`<a href="https://wa.me/${esc(String(u.whatsapp).replace(/\D/g,''))}" target="_blank" rel="noopener">${esc(u.whatsapp)}</a>`:''}</td><td><span class="status-pill ${st}">${esc(u.status)}</span></td><td>${etaxesProfile}</td><td>${access}</td><td>${devices}</td><td>${esc(String(u.last_login_at||'').replace('T',' ').slice(0,19))}</td><td class="admin-action-cell">${actions}</td></tr>`}).join('');
  document.querySelectorAll('.adm-approve').forEach(b=>b.onclick=()=>adminAction(`/api/admin/users/${encodeURIComponent(b.dataset.id)}/approve`));document.querySelectorAll('.adm-disable').forEach(b=>b.onclick=()=>adminAction(`/api/admin/users/${encodeURIComponent(b.dataset.id)}/disable`));document.querySelectorAll('.adm-enable').forEach(b=>b.onclick=()=>adminAction(`/api/admin/users/${encodeURIComponent(b.dataset.id)}/enable`));document.querySelectorAll('.adm-reset').forEach(b=>b.onclick=()=>adminAction(`/api/admin/users/${encodeURIComponent(b.dataset.id)}/reset-devices`,true));document.querySelectorAll('.adm-delete').forEach(b=>b.onclick=()=>adminDelete(b.dataset.id));document.querySelectorAll('.adm-device-approve').forEach(b=>b.onclick=()=>adminAction(`/api/admin/users/${encodeURIComponent(b.dataset.uid)}/devices/${encodeURIComponent(b.dataset.did)}/approve`,true));document.querySelectorAll('.adm-sections').forEach(b=>b.onclick=()=>openAdminSectionPermissions(b.dataset.id,b.dataset.user));
  document.querySelectorAll('.adm-etaxes-save').forEach(b=>b.onclick=()=>saveAdminEtaxesProfile(b.dataset.id,b.closest('.admin-etaxes-profile')));document.querySelectorAll('.adm-access-save').forEach(b=>b.onclick=()=>saveAccessWindow(b.dataset.id,b.closest('.admin-access')));document.querySelectorAll('.adm-access-quick').forEach(b=>b.onclick=()=>quickAccessWindow(b.dataset.id,Number(b.dataset.days)));document.querySelectorAll('.adm-access-unlimited').forEach(b=>b.onclick=()=>setAccessWindow(b.dataset.id,null,null));
}
async function saveAdminEtaxesProfile(id,box){const phone=box?.querySelector('.adm-etx-phone')?.value.trim()||'',userId=box?.querySelector('.adm-etx-userid')?.value.trim()||'',tin=(box?.querySelector('.adm-etx-tin')?.value||'').replace(/\D/g,'');if(phone.replace(/\D/g,'').length<9)return toast('ASAN İmza telefon nömrəsini düzgün yazın.');if(!/^\d{1,20}$/.test(userId))return toast('ASAN İmza İstifadəçi ID yalnız rəqəmlərdən ibarət olmalıdır.');if(tin.length!==10)return toast('VÖEN 10 rəqəm olmalıdır.');try{const d=await api(`/api/admin/users/${encodeURIComponent(id)}/etaxes-profile`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone,userId,tin})});toast(d.message||'e‑Taxes profili yadda saxlanıldı.');await loadAdminUsers()}catch(e){toast(e.message)}}

async function loadAdminSectionOverview(showToast=false){try{const d=await api('/api/admin/section-access');if($('autoApproveRegistrations'))$('autoApproveRegistrations').checked=!!d.autoApproveRegistration;if($('adminPendingAccessCount'))$('adminPendingAccessCount').textContent=String(d.pendingCount||0);const strip=$('adminPendingAccessStrip'),rows=d.pendingRequests||[];if(strip){strip.classList.toggle('hidden',!rows.length);strip.innerHTML=rows.length?`<b>Gözləyən bölmə istəkləri:</b> `+rows.map(r=>`<button class="mini ghost pending-request-open" data-id="${esc(r.userId)}" data-user="${esc(r.username)}">${esc(r.username)} · ${esc(r.sectionLabel)}</button>`).join(' '):'';strip.querySelectorAll('.pending-request-open').forEach(b=>b.onclick=()=>openAdminSectionPermissions(b.dataset.id,b.dataset.user))}return d}catch(e){if(showToast)toast(e.message);throw e}}
async function openAdminSectionPermissions(userId,username){adminSectionUser={id:userId,username};$('adminSectionPermissionTitle').textContent=`${username} · Bölmə səlahiyyətləri`;$('adminSectionPermissionModal').classList.remove('hidden');$('adminSectionPermissionList').innerHTML='<div class="permission-empty">İcazələr yüklənir...</div>';try{const d=await api(`/api/admin/users/${encodeURIComponent(userId)}/sections`);renderAdminSectionPermissions(d)}catch(e){toast(e.message)}}
function renderAdminSectionPermissions(d){const box=$('adminSectionPermissionList');if(!box)return;box.innerHTML=(d.sections||[]).map(x=>{const pending=x.requestStatus==='PENDING',approved=x.requestStatus==='APPROVED',rejected=x.requestStatus==='REJECTED';const requestBadge=pending?'<span class="permission-badge pending">İstifadəçi bu bölməni istəyib</span>':approved?'<span class="permission-badge allowed">Sorğu təsdiqlənib</span>':rejected?'<span class="permission-badge rejected">Sorğu rədd edilib</span>':'';return `<div class="permission-row admin-permission-row"><label class="permission-check"><input type="checkbox" class="admin-section-check" data-key="${esc(x.key)}" ${x.allowed?'checked':''}><span><b>${esc(x.label)}</b><small>${x.allowed?'İstifadəçi hazırda bu bölməni görür.':'İstifadəçi hazırda bu bölməni görmür.'}</small></span></label><div class="permission-row-actions">${requestBadge}${pending?`<button class="mini success admin-request-decision" data-key="${esc(x.key)}" data-approve="true">Təsdiqlə</button><button class="mini danger admin-request-decision" data-key="${esc(x.key)}" data-approve="false">Rədd et</button>`:''}</div></div>`}).join('');box.querySelectorAll('.admin-request-decision').forEach(b=>b.onclick=()=>decideAdminSectionRequest(b.dataset.key,b.dataset.approve==='true'))}
async function saveAdminSectionPermissions(){if(!adminSectionUser)return;const allowed=[...document.querySelectorAll('#adminSectionPermissionList .admin-section-check:checked')].map(x=>x.dataset.key);try{const d=await api(`/api/admin/users/${encodeURIComponent(adminSectionUser.id)}/sections`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({allowedSections:allowed})});renderAdminSectionPermissions(d);toast('Bölmə səlahiyyətləri yadda saxlanıldı.');await Promise.all([loadAdminSectionOverview(false),api('/api/admin/users').then(x=>renderAdminUsers(x.users||[]))])}catch(e){toast(e.message)}}
async function decideAdminSectionRequest(sectionKey,approve){if(!adminSectionUser)return;try{const d=await api('/api/admin/section-requests/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:adminSectionUser.id,sectionKey,approve})});renderAdminSectionPermissions(d);toast(approve?'Bölmə icazəsi təsdiqləndi.':'Bölmə istəyi rədd edildi.');await Promise.all([loadAdminSectionOverview(false),api('/api/admin/users').then(x=>renderAdminUsers(x.users||[]))])}catch(e){toast(e.message)}}
async function setAccessWindow(id,start,end){try{await api(`/api/admin/users/${encodeURIComponent(id)}/access-window`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start,end})});toast('İstifadə müddəti yeniləndi. Aktiv sessiya yenidən giriş tələb edəcək.');await loadAdminUsers()}catch(e){toast(e.message)}}
async function saveAccessWindow(id,box){const sv=box?.querySelector('.adm-access-start')?.value||'',ev=box?.querySelector('.adm-access-end')?.value||'';const start=sv?new Date(sv).toISOString():null,end=ev?new Date(ev).toISOString():null;if(start&&end&&new Date(end)<=new Date(start))return toast('Bitmə vaxtı başlama vaxtından sonra olmalıdır.');await setAccessWindow(id,start,end)}
async function quickAccessWindow(id,days){const start=new Date(),end=new Date(Date.now()+days*86400000);await setAccessWindow(id,start.toISOString(),end.toISOString())}
async function adminAction(url,confirmIt=false){if(confirmIt&&!confirm('Bu əməliyyat mövcud sessiyanı/cihaz icazəsini dəyişə bilər. Davam edilsin?'))return;try{await api(url,{method:'POST'});await loadAdminUsers()}catch(e){toast(e.message)}}
async function adminDelete(id){if(!confirm('İstifadəçi login bazasından silinsin? Onun 3 günlük PostgreSQL cloud backup-ları hesabla birlikdə silinəcək; istifadəçinin öz kompüterindəki lokal backup avtomatik silinməyəcək.'))return;try{await api(`/api/admin/users/${encodeURIComponent(id)}`,{method:'DELETE'});await loadAdminUsers()}catch(e){toast(e.message)}}
$('adminPanelBtn').onclick=async()=>{$('adminModal').classList.remove('hidden');await loadAdminUsers()};$('closeAdminModal').onclick=()=>$('adminModal').classList.add('hidden');$('refreshAdminUsers').onclick=loadAdminUsers;$('adminUserSearch').oninput=()=>loadAdminUsers();
$('refreshAdminSectionAccess')?.addEventListener('click',()=>loadAdminSectionOverview(true));
$('autoApproveRegistrations')?.addEventListener('change',async e=>{const enabled=!!e.target.checked;try{await api('/api/admin/settings/auto-approve-registration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});toast(enabled?'Yeni qeydiyyatlar avtomatik aktiv ediləcək.':'Yeni qeydiyyatlar yenidən admin təsdiqi gözləyəcək.')}catch(err){e.target.checked=!enabled;toast(err.message)}});
$('closeAdminSectionPermission')?.addEventListener('click',()=>$('adminSectionPermissionModal').classList.add('hidden'));$('selectAllAdminSections')?.addEventListener('click',()=>document.querySelectorAll('#adminSectionPermissionList .admin-section-check').forEach(x=>x.checked=true));$('clearAllAdminSections')?.addEventListener('click',()=>document.querySelectorAll('#adminSectionPermissionList .admin-section-check').forEach(x=>x.checked=false));$('saveAdminSectionPermissions')?.addEventListener('click',saveAdminSectionPermissions);$('adminSectionPermissionModal')?.addEventListener('click',e=>{if(e.target===$('adminSectionPermissionModal'))$('adminSectionPermissionModal').classList.add('hidden')});

async function autoSaveRemoteFile(url,name,folder){if(!currentUser?.id||!url)return false;try{const info=await LocalWorkspaceStore.info(currentUser.id);if(!info.hasFolder)return false;await LocalWorkspaceStore.saveUrl(currentUser.id,url,name,folder);return true}catch(e){console.warn('Auto local save skipped:',e);return false}}

async function bootstrap(){
  try{const w=await api('/api/workspace/state');state.activeTemplates=w.activeTemplates||{};state.templateMappings=w.templateMappings||{};state.printCopies={...state.printCopies,...(w.printCopies||{})};applyPrintCopies();updateTemplateLinks();updateTemplateStatuses()}catch(e){console.warn(e)}
  const jobs=[];if(hasSectionAccess('01')||hasSectionAccess('04')||hasSectionAccess('06'))jobs.push(loadCompanies());if(hasSectionAccess('02')||hasSectionAccess('04'))jobs.push(loadInvoices());if(hasSectionAccess('06'))jobs.push(loadOutgoing());if(hasSectionAccess('03'))jobs.push(loadEtaxesBrowserStatus());await Promise.all(jobs);
  if(hasSectionAccess('03'))await resumeEtxTask();
}

