$('exportWorkspace').onclick=async e=>{e.preventDefault();if(!currentUser)return;try{await flushLocalSnapshot('manual export');await LocalWorkspaceStore.exportBackup(currentUser);await refreshLocalStorageInfo();toast('Lokal workspace ZIP bu kompüterə endirildi.')}catch(err){toast(err.message)}};
$('importWorkspace').onclick=async()=>{const file=$('workspaceImportFile').files[0];if(!file)return toast('Backup ZIP seçilməyib.');if(!confirm('Bu kompüterdəki cari lokal workspace backup-dakı məlumatlarla əvəz ediləcək. Davam edilsin?'))return;try{const d=await LocalWorkspaceStore.importBackup(currentUser,file);state.selected.clear();await Promise.all([loadCompanies(),loadInvoices(),loadOutgoing(),loadContracts(),loadDocumentArchive()]);const w=await api('/api/workspace/state');state.activeTemplates=w.activeTemplates||{};state.templateMappings=w.templateMappings||{};state.printCopies=w.printCopies||state.printCopies;updateTemplateLinks();updateTemplateStatuses();await refreshLocalStorageInfo();await flushCloudSnapshot('manual-import',true).catch(e=>console.warn(e));toast(`Lokal backup bərpa edildi: ${d.companyCount} rekvizit, ${d.invoiceCount} qaimə.`)}catch(e){toast(e.message)}};
$('exportFullTransfer').onclick=async()=>{if(!currentUser)return;const p1=prompt('Tam Transfer Backup üçün ən azı 10 simvolluq parol yazın. Bu parol faylın içində saxlanmır; itirsəniz backup açıla bilməz.');if(p1===null)return;if(p1.length<10)return toast('Transfer parolu ən azı 10 simvol olmalıdır.');const p2=prompt('Parolu təkrar yazın:');if(p2===null)return;if(p1!==p2)return toast('Parollar eyni deyil.');try{await flushLocalSnapshot('tam transfer export');const activePage=localStorage.getItem('taxdata.activePage')||'';const d=await LocalWorkspaceStore.exportFullTransfer(currentUser,p1,{activePage});toast(`Tam Transfer Backup yaradıldı (${LocalWorkspaceStore.fmtBytes(d.bytes)}). Bu .tdbackup faylını başqa kompüterə ötürə bilərsiniz.`)}catch(e){toast(e.message)}};
$('restoreFullTransfer').onclick=async()=>{if(!currentUser)return;const file=$('fullTransferFile').files[0];if(!file)return toast('Tam Transfer .tdbackup faylı seçilməyib.');const password=prompt('Bu Tam Transfer Backup üçün parolu yazın:');if(password===null)return;if(password.length<10)return toast('Transfer parolu ən azı 10 simvol olmalıdır.');if(!confirm('Cari lokal workspace və bu hesabın SQL rekvizit bazası seçilmiş Tam Transfer Backup ilə əvəz ediləcək. Login/rol/bölmə icazələri və server təhlükəsizlik məlumatları dəyişməyəcək. Davam edilsin?'))return;try{const d=await LocalWorkspaceStore.restoreFullTransfer(currentUser,file,password);if(d.browserSettings?.activePage)try{localStorage.setItem('taxdata.activePage',d.browserSettings.activePage)}catch{}state.selected.clear();await Promise.all([loadCompanies(),loadInvoices(),loadOutgoing(),loadContracts(),loadDocumentArchive()]);const w=await api('/api/workspace/state');state.activeTemplates=w.activeTemplates||{};state.templateMappings=w.templateMappings||{};state.printCopies=w.printCopies||state.printCopies;updateTemplateLinks();updateTemplateStatuses();await refreshLocalStorageInfo(d.record);await flushCloudSnapshot('tam-transfer-restore',true).catch(e=>console.warn(e));const src=d.sourceUsername?` Mənbə: ${d.sourceUsername}.`:'';toast(`Tam Transfer bərpa edildi: ${d.companyCount} rekvizit, ${d.invoiceCount} qaimə.${src}`)}catch(e){toast(e.message)}};
$('chooseLocalFolder').onclick=async()=>{if(!currentUser)return;try{const h=await LocalWorkspaceStore.chooseDirectory(currentUser.id);await refreshLocalStorageInfo();toast(`Lokal qovluq seçildi: ${h.name}. Bundan sonra backup və yaradılan paketlər həmin kompüterdə də saxlanacaq.`)}catch(e){toast(e.message)}};
$('saveBackupToFolder').onclick=async()=>{if(!currentUser)return;try{await flushLocalSnapshot('qovluğa manual backup');const n=await LocalWorkspaceStore.copyLatestBackupToFolder(currentUser);await refreshLocalStorageInfo();toast(`Backup seçilən lokal qovluğa yazıldı (${LocalWorkspaceStore.fmtBytes(n)}).`)}catch(e){toast(e.message)}};
$('cloudBackupNow').onclick=async()=>{if(!currentUser)return;try{await flushLocalSnapshot('manual cloud backup');const d=await flushCloudSnapshot('manual',true);toast(`Cloud backup saxlanıldı · ${d?.backup?.zipSizeBytes?LocalWorkspaceStore.fmtBytes(d.backup.zipSizeBytes):'hazırdır'}.`)}catch(e){toast(e.message)}};
$('cloudRestoreLatest').onclick=async()=>{if(!currentUser)return;if(!confirm('Bu kompüterdəki cari workspace ən son cloud backup ilə əvəz ediləcək. Davam edilsin?'))return;try{const d=await LocalWorkspaceStore.restoreCloudLatest(currentUser);state.selected.clear();await Promise.all([loadCompanies(),loadInvoices(),loadOutgoing(),loadContracts(),loadDocumentArchive()]);const w=await api('/api/workspace/state');state.activeTemplates=w.activeTemplates||{};state.templateMappings=w.templateMappings||{};state.printCopies=w.printCopies||state.printCopies;updateTemplateLinks();updateTemplateStatuses();await refreshLocalStorageInfo(d.record);toast(`Cloud backup bərpa edildi: ${d.companyCount} rekvizit, ${d.invoiceCount} qaimə.`)}catch(e){toast(e.message)}};
$('cloudDownloadLatest').onclick=async()=>{if(!currentUser)return;try{const n=await LocalWorkspaceStore.downloadCloudLatest(currentUser);toast(`Cloud ZIP endirildi (${LocalWorkspaceStore.fmtBytes(n)}). Bu faylı başqa istifadəçiyə/kompüterə ötürüb Lokal backup bərpa et ilə aça bilərsiniz.`)}catch(e){toast(e.message)}};

// Companies
async function loadCompanies(){try{const d=await api('/api/companies/defaults');state.companies=d.companies||[];fillCompanies();renderCompanyRegistry();$('companyStatus').textContent=`SQL rekvizit bazasında ${state.companies.length} qeyd var.`}catch(e){$('companyStatus').textContent=e.message}}
$('uploadCompanies').onclick=async()=>{const file=$('companyFile').files[0];if(!file)return toast('Şirkət Excel-i seçilməyib.');const fd=new FormData();fd.append('file',file);$('companyStatus').textContent='Excel yoxlanılır və yalnız yeni rekvizitlər əlavə edilir...';try{const d=await api('/api/companies/upload',{method:'POST',body:fd});state.companies=d.companies||[];fillCompanies();renderCompanyRegistry();$('companyStatus').textContent=`${file.name}: ${d.parsed} sətir oxundu · ${d.added} yeni əlavə edildi · ${d.skipped} mövcud olduğu üçün atlandı.`;toast(`${d.added} yeni rekvizit əlavə edildi.`)}catch(e){$('companyStatus').textContent=e.message;toast(e.message)}};
function fillCompanies(){
  const oldEx=$('executorCompany').value,oldOr=$('ordererCompany').value;
  const opts='<option value="">Tərəfi seç</option>'+state.companies.map(c=>`<option value="${esc(c.id)}">${esc(c.company)} · ${entityLabel(entityFromVoen(c.voen,c.entityType))}${c.role?' · '+esc(c.role):''}</option>`).join('');
  $('executorCompany').innerHTML=opts;$('ordererCompany').innerHTML=opts;
  if(state.companies.some(c=>c.id===oldEx))$('executorCompany').value=oldEx;
  if(state.companies.some(c=>c.id===oldOr))$('ordererCompany').value=oldOr;
  if(!$('executorCompany').value){const c=state.companies.find(x=>(x.role||'').toUpperCase().includes('İCRA'));if(c)$('executorCompany').value=c.id}
  if(!$('ordererCompany').value){const c=state.companies.find(x=>(x.role||'').toUpperCase().includes('SİFAR'));if(c)$('ordererCompany').value=c.id}
  refreshCompanyPickers();syncOrdererFields();autoMatchParties();
}
const companyById=id=>state.companies.find(c=>c.id===id);
function selectedOrdererEntity(){const c=companyById($('ordererCompany').value);return entityFromVoen(c?.voen,c?.entityType||'LEGAL')}
function syncOrdererFields(){const c=companyById($('ordererCompany').value);if(!c){$('ordererTypeInfo').textContent='';$('contractNo').value='';$('contractDate').value='';return}$('contractNo').value=c.contractNo||'';$('contractDate').value=c.contractDate||'';const e=selectedOrdererEntity();$('ordererTypeInfo').textContent=`Avtomatik tip: ${entityLabel(e)}${c.voen?' · VÖEN '+c.voen:''}`;$('templateEntityType').value=e;updateTemplateLinks();updateTemplateStatuses()}
