const COMPANY_PICKERS={
  executorCompany:{search:'executorCompanySearch',menu:'executorCompanyMenu',clear:'executorCompanyClear',role:'icra'},
  ordererCompany:{search:'ordererCompanySearch',menu:'ordererCompanyMenu',clear:'ordererCompanyClear',role:'sifaris'}
};
function companyPickerLabel(c){return c?`${c.company||'Adsız'}${c.voen?' · '+c.voen:''}`:''}
function pickerMatches(c,q){if(!q)return true;return [c.company,c.voen,c.role,c.director,c.address,entityLabel(entityFromVoen(c.voen,c.entityType))].some(v=>normalize(v).includes(q))}
function pickerOrdered(role,q){return state.companies.filter(c=>pickerMatches(c,q)).sort((a,b)=>Number(normalize(b.role).includes(role))-Number(normalize(a.role).includes(role))||(a.company||'').localeCompare(b.company||'','az')).slice(0,40)}
function renderCompanyPickerMenu(selectId){const cfg=COMPANY_PICKERS[selectId],input=$(cfg.search),menu=$(cfg.menu);if(!input||!menu)return;const q=normalize(input.value),list=pickerOrdered(cfg.role,q);menu.innerHTML=list.length?list.map(c=>`<button type="button" class="company-picker-option ${$(''+selectId).value===c.id?'selected':''}" data-id="${esc(c.id)}" role="option"><span><b>${esc(c.company||'Adsız')}</b><small>${esc(c.voen||'VÖEN yoxdur')} · ${esc(c.role||entityLabel(entityFromVoen(c.voen,c.entityType)))}</small></span><i>Seç</i></button>`).join(''):`<div class="company-picker-empty">Uyğun rekvizit tapılmadı.</div>`;menu.classList.remove('hidden');menu.querySelectorAll('.company-picker-option').forEach(b=>b.onclick=()=>setCompanyPickerValue(selectId,b.dataset.id,true))}
function syncCompanyPickerInput(selectId){const cfg=COMPANY_PICKERS[selectId];if(!cfg)return;const c=companyById($(selectId).value),input=$(cfg.search),clear=$(cfg.clear);if(input)input.value=companyPickerLabel(c);if(clear)clear.classList.toggle('hidden',!c)}
function setCompanyPickerValue(selectId,id,emit=true){const cfg=COMPANY_PICKERS[selectId],select=$(selectId);if(!cfg||!select)return;select.value=id||'';syncCompanyPickerInput(selectId);$(cfg.menu)?.classList.add('hidden');if(emit)select.dispatchEvent(new Event('change',{bubbles:true}))}
function refreshCompanyPickers(){Object.keys(COMPANY_PICKERS).forEach(syncCompanyPickerInput)}
function initCompanyPickers(){
  Object.entries(COMPANY_PICKERS).forEach(([selectId,cfg])=>{const input=$(cfg.search),menu=$(cfg.menu),clear=$(cfg.clear);if(!input||!menu)return;
    input.addEventListener('focus',()=>{input.select();renderCompanyPickerMenu(selectId)});
    input.addEventListener('input',()=>{const selected=companyById($(selectId).value);if(selected&&input.value!==companyPickerLabel(selected)){$(selectId).value='';if(clear)clear.classList.add('hidden');$(selectId).dispatchEvent(new Event('change',{bubbles:true}))}renderCompanyPickerMenu(selectId)});
    input.addEventListener('keydown',e=>{const buttons=[...menu.querySelectorAll('.company-picker-option')];if(e.key==='Escape'){menu.classList.add('hidden');input.blur();return}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;if(menu.classList.contains('hidden'))renderCompanyPickerMenu(selectId);const live=[...menu.querySelectorAll('.company-picker-option')],cur=live.findIndex(x=>x.classList.contains('keyboard-active'));if(e.key==='Enter'){const pick=live[cur>=0?cur:0];if(pick){e.preventDefault();setCompanyPickerValue(selectId,pick.dataset.id,true)}return}e.preventDefault();live.forEach(x=>x.classList.remove('keyboard-active'));const next=e.key==='ArrowDown'?Math.min(cur+1,live.length-1):Math.max(cur<0?live.length-1:cur-1,0);live[next]?.classList.add('keyboard-active');live[next]?.scrollIntoView({block:'nearest'})});
    clear?.addEventListener('click',()=>{setCompanyPickerValue(selectId,'',true);input.focus();renderCompanyPickerMenu(selectId)});
  });
  document.addEventListener('click',e=>{for(const cfg of Object.values(COMPANY_PICKERS)){const input=$(cfg.search),menu=$(cfg.menu);if(menu&&!menu.contains(e.target)&&e.target!==input&&!e.target.closest?.('.picker-clear'))menu.classList.add('hidden')}});
  refreshCompanyPickers();
}
