function matchCompany(name,voen=''){const tax=String(voen||'').replace(/\D/g,'');if(tax){const byTax=state.companies.find(c=>String(c.voen||'').replace(/\D/g,'')===tax);if(byTax)return byTax}const n=normalize(name);if(!n)return null;return state.companies.find(c=>normalize(c.company)===n)||state.companies.find(c=>{const cn=normalize(c.company);return cn&&(cn.includes(n)||n.includes(cn))})}
function autoMatchParties(){const selected=state.invoices.filter(x=>state.selected.has(x.eInvoiceNumber));if(!selected.length)return;const sellers=[...new Set(selected.map(x=>String(x.sellerVoen||'').replace(/\D/g,'')||normalize(x.sellerName)).filter(Boolean))],buyers=[...new Set(selected.map(x=>String(x.buyerVoen||'').replace(/\D/g,'')||normalize(x.buyerName)).filter(Boolean))];if(sellers.length===1){const x=selected[0],c=matchCompany(x.sellerName,x.sellerVoen);if(c){setCompanyPickerValue('executorCompany',c.id,false);$('executorMatchInfo').textContent=`Excel Satıcı: ${x.sellerName||''}${x.sellerVoen?' · VÖEN '+x.sellerVoen:''}`}}if(buyers.length===1){const x=selected[0],c=matchCompany(x.buyerName,x.buyerVoen);if(c){setCompanyPickerValue('ordererCompany',c.id,true)}}}

