function validateGeneration(){if(!state.selected.size)throw new Error('Ən azı bir qaimə seç.');const selected=state.invoices.filter(x=>state.selected.has(x.eInvoiceNumber));const exFallback=companyById($('executorCompany').value),orFallback=companyById($('ordererCompany').value);for(const x of selected){if(String(x.sellerName||'').trim()){if(!matchCompany(x.sellerName,x.sellerVoen))throw new Error(`${x.eInvoiceNumber}: Satıcı “${x.sellerName}” SQL rekvizit bazasında tapılmadı.`)}else if(!exFallback)throw new Error(`${x.eInvoiceNumber}: Satıcı adı Excel-də boşdur; fallback İcraçı seçin.`);if(String(x.buyerName||'').trim()){if(!matchCompany(x.buyerName,x.buyerVoen))throw new Error(`${x.eInvoiceNumber}: Alıcı “${x.buyerName}” SQL rekvizit bazasında tapılmadı.`)}else if(!orFallback)throw new Error(`${x.eInvoiceNumber}: Alıcı adı Excel-də boşdur; fallback Sifarişçi seçin.`)}if(!/^\d+$/.test($('startingDocumentNo').value.trim()||'1'))throw new Error('Başlanğıc sənəd № yalnız rəqəm olmalıdır.')}
let documentPreviewBlobUrl='';
async function loadDocumentPreview(url){const frame=$('documentPreviewFrame');if(!frame||!url)return;try{frame.removeAttribute('srcdoc');frame.src='about:blank';const r=await fetch(url,{credentials:'same-origin',headers:{'Accept':'text/html'}});if(!r.ok){let msg='';try{msg=(await r.json()).error||''}catch{}throw new Error(msg||`Ön baxış yüklənmədi (HTTP ${r.status}).`)}const html=await r.text();if(documentPreviewBlobUrl)URL.revokeObjectURL(documentPreviewBlobUrl);documentPreviewBlobUrl=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));frame.src=documentPreviewBlobUrl}catch(e){frame.src='about:blank';toast(e.message||'Sənədlərin tam ön baxışı açıla bilmədi.');}}
function renderGenerationResult(d){if(window.taxDataShowPage)window.taxDataShowPage('documents');$('resultCard').classList.remove('hidden');$('resultText').textContent=`${d.results.length} qaimə tarixə görə köhnədən yeniyə nömrələndi; hər qaimənin HF, QR və TT sənədlərində eyni sıra № istifadə edildi.`;$('downloadZip').href=d.downloadUrl;$('generatedFiles').innerHTML=d.results.map(r=>`<div class="generated-set"><div><b>Sənəd № ${esc(r.documentNumber)} · Qaimə ${esc(r.eInvoiceNumber||'')}</b><span>MT ${esc(r.mtNumber||'')}</span></div><div class="file-links">${r.documents.map(x=>`<a href="${esc(x.downloadUrl)}">${x.type.toUpperCase()} endir</a>`).join('')}</div></div>`).join('');loadDocumentPreview(d.previewUrl);applyPrintCopies();$('resultCard').scrollIntoView({behavior:'smooth'})}

