function applyPrintCopies(){$('hfCopies').value=state.printCopies.hf??1;$('ttCopies').value=state.printCopies.tt??2;$('qrCopies').value=state.printCopies.qr??2}const clampCopy=v=>Math.max(0,Math.min(20,Number(v)||0));
$('printAll').onclick=async()=>{if(!state.lastResult)return toast('Əvvəl sənədləri yarat.');const copies={hf:clampCopy($('hfCopies').value),tt:clampCopy($('ttCopies').value),qr:clampCopy($('qrCopies').value)};state.printCopies=copies;const printWindow=window.open('about:blank','taxdataPrint');if(printWindow){try{printWindow.opener=null;printWindow.document.title='TaxData · Çap hazırlanır';printWindow.document.body.innerHTML='<p style="font-family:Arial,sans-serif;padding:24px">Çap sənədi hazırlanır...</p>'}catch{}}try{await api('/api/workspace/print-copies',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(copies)})}catch{}const sep=state.lastResult.printUrl.includes('?')?'&':'?';const url=`${state.lastResult.printUrl}${sep}hfCopies=${copies.hf}&ttCopies=${copies.tt}&qrCopies=${copies.qr}&autoprint=1`;if(printWindow)printWindow.location.replace(url);else{toast('Brauzer çap pəncərəsini blokladı. Pop-up icazəsini aktiv edib yenidən “Printer seç və çap et” düyməsinə basın.')}};


