async function loadDocumentArchive(){try{const d=await api('/api/document-archive');state.documentArchives=d.records||[];state.documentArchiveFolder=d.folder||'';if($('documentArchiveStatus'))$('documentArchiveStatus').textContent=`${state.documentArchives.length} alt sənəd paketi lokal workspace arxivindədir.`;if($('documentArchiveFolderInfo'))$('documentArchiveFolderInfo').textContent='Arxiv master backup-la bu kompüterdə saxlanılır. Lokal qovluq seçilibsə faylları ora da yaza bilərsiniz.';renderDocumentArchive()}catch(e){if($('documentArchiveStatus'))$('documentArchiveStatus').textContent=e.message}}
function archiveValues(r){return [...(r.invoiceNumbers||[]),...Object.values(r.documentNumbers||{}),...Object.values(r.buyerNames||{}),...Object.values(r.sellerNames||{}),...Object.values(r.contractNumbers||{}),r.folderName,r.relativePath,r.startingDocumentNo]}
function renderDocumentArchive(){if(!$('documentArchiveBody'))return;const q=normalize($('documentArchiveSearch')?.value);const list=state.documentArchives.filter(r=>!q||archiveValues(r).some(v=>normalize(v).includes(q)));$('documentArchiveBody').innerHTML=list.map(r=>{const docs=[...new Set(Object.values(r.documentNumbers||{}).filter(Boolean))].join(', '),invs=(r.invoiceNumbers||[]).join(', '),buyers=[...new Set(Object.values(r.buyerNames||{}).filter(Boolean))].join(' / '),sellers=[...new Set(Object.values(r.sellerNames||{}).filter(Boolean))].join(' / '),contracts=[...new Set(Object.values(r.contractNumbers||{}).filter(Boolean))].join(', '),created=r.createdAt?String(r.createdAt).replace('T',' ').slice(0,16):'';return `<tr><td>${esc(created)}</td><td class="clip" title="${esc(invs)}"><b>${esc(invs)}</b></td><td>${esc(docs||r.startingDocumentNo||'')}</td><td><b>Alıcı:</b> ${esc(buyers)}<br><b>Satıcı:</b> ${esc(sellers)}</td><td>${esc(contracts)}</td><td class="clip" title="${esc(r.relativePath||'')}">${esc(r.folderName||'')}</td><td><button class="mini docarc-preview" data-id="${esc(r.id)}">Bax</button> <button class="mini docarc-print" data-id="${esc(r.id)}">Çap</button> <button class="mini docarc-edit" data-id="${esc(r.id)}">Düzəliş / təkrar yarat</button> <button class="mini docarc-files" data-id="${esc(r.id)}">Fayllar</button> <button class="mini docarc-open" data-id="${esc(r.id)}">ZIP-i lokal qovluğa yaz</button> <button class="mini docarc-download" data-id="${esc(r.id)}">ZIP endir</button> <button class="mini danger docarc-delete" data-id="${esc(r.id)}">Sil</button></td></tr>`}).join('');document.querySelectorAll('.docarc-preview').forEach(b=>b.onclick=()=>openArchivePreview(b.dataset.id,false));document.querySelectorAll('.docarc-print').forEach(b=>b.onclick=()=>openArchivePreview(b.dataset.id,true));document.querySelectorAll('.docarc-edit').forEach(b=>b.onclick=()=>loadArchiveForEdit(b.dataset.id));document.querySelectorAll('.docarc-files').forEach(b=>b.onclick=()=>showArchiveFiles(b.dataset.id));document.querySelectorAll('.docarc-open').forEach(b=>b.onclick=()=>openArchiveFolder(b.dataset.id));document.querySelectorAll('.docarc-download').forEach(b=>b.onclick=async()=>{try{const r=archiveById(b.dataset.id);await downloadWithWorkspace(`/api/output/${encodeURIComponent(r.folderName)}/${encodeURIComponent(r.zipFileName||'alt_senedler.zip')}`,r.zipFileName||'alt_senedler.zip')}catch(e){toast(e.message)}});document.querySelectorAll('.docarc-delete').forEach(b=>b.onclick=()=>deleteDocumentArchive(b.dataset.id))}
function archiveById(id){return state.documentArchives.find(r=>r.id===id)}
async function openArchivePreview(id,print){const r=archiveById(id);if(!r)return toast('Arxiv qeydi tapılmadı.');try{await api('/api/workspace/state');const copies=state.printCopies||{hf:1,tt:2,qr:2};const u=`/api/print/${encodeURIComponent(r.folderName)}?hfCopies=${print?(copies.hf??1):1}&ttCopies=${print?(copies.tt??2):1}&qrCopies=${print?(copies.qr??2):1}&${print?'autoprint=1':'preview=1'}`;window.open(u,'_blank','noopener')}catch(e){toast(e.message)}}
async function openArchiveFolder(id){const r=archiveById(id);if(!r)return toast('Arxiv qeydi tapılmadı.');try{const info=await LocalWorkspaceStore.info(currentUser.id);if(!info.hasFolder)await LocalWorkspaceStore.chooseDirectory(currentUser.id);const name=r.zipFileName||'alt_senedler.zip';await LocalWorkspaceStore.saveUrl(currentUser.id,`/api/output/${encodeURIComponent(r.folderName)}/${encodeURIComponent(name)}`,`${r.folderName||'alt_senedler'}.zip`,'TaxData_Alt_Senedler');await refreshLocalStorageInfo();toast('Alt sənəd ZIP-i bu kompüterdə seçilmiş lokal qovluğa yazıldı.')}catch(e){toast(e.message)}}
async function showArchiveFiles(id){try{const d=await api(`/api/document-archive/${encodeURIComponent(id)}`),r=d.record;$('documentFilesPath').textContent='Fayllar müvəqqəti server sessiyasında göstərilir; “Lokal qovluğa yaz” onları istifadəçinin öz kompüterinə saxlayır.';$('documentFilesBody').innerHTML=(d.files||[]).map(f=>`<tr><td><b>${esc(f)}</b></td><td><button class="mini docfile-open" data-id="${esc(id)}" data-file="${esc(f)}">Lokal qovluğa yaz</button> <button class="mini docfile-download" data-id="${esc(id)}" data-file="${esc(f)}">Endir</button></td></tr>`).join('');document.querySelectorAll('.docfile-open').forEach(b=>b.onclick=async()=>{try{const info=await LocalWorkspaceStore.info(currentUser.id);if(!info.hasFolder)await LocalWorkspaceStore.chooseDirectory(currentUser.id);await LocalWorkspaceStore.saveUrl(currentUser.id,`/api/output/${encodeURIComponent(r.folderName)}/${encodeURIComponent(b.dataset.file)}`,b.dataset.file,'TaxData_Alt_Senedler');toast('Fayl bu kompüterdə seçilmiş lokal qovluğa yazıldı.')}catch(e){toast(e.message)}});document.querySelectorAll('.docfile-download').forEach(b=>b.onclick=async()=>{try{await downloadWithWorkspace(`/api/output/${encodeURIComponent(r.folderName)}/${encodeURIComponent(b.dataset.file)}`,b.dataset.file)}catch(e){toast(e.message)}});$('documentFilesModal').classList.remove('hidden')}catch(e){toast(e.message)}}
async function deleteDocumentArchive(id){if(!confirm('Bu alt sənəd arxiv qeydi və onun HF/QR/TT faylları kompüterdən silinsin?'))return;try{await api(`/api/document-archive/${encodeURIComponent(id)}?deleteFiles=true`,{method:'DELETE'});await loadDocumentArchive();toast('Alt sənəd paketi arxivdən silindi.')}catch(e){toast(e.message)}}
async function loadArchiveForEdit(id){const r=archiveById(id);if(!r)return toast('Arxiv qeydi tapılmadı.');const available=new Set(state.invoices.map(x=>x.eInvoiceNumber));state.selected.clear();const missing=[];(r.invoiceNumbers||[]).forEach(no=>available.has(no)?state.selected.add(no):missing.push(no));if(r.executorCompanyId&&companyById(r.executorCompanyId))$('executorCompany').value=r.executorCompanyId;if(r.ordererCompanyId&&companyById(r.ordererCompanyId)){$('ordererCompany').value=r.ordererCompanyId;syncOrdererFields()}$('startingDocumentNo').value=r.startingDocumentNo||'1';$('documentDate').value=r.documentDate||'';$('contractNo').value=r.contractNo||'';$('contractDate').value=r.contractDate||'';$('noteOverride').value=cleanNote(r.noteOverride||'');renderInvoiceList();updateSelectedCount();autoMatchParties();$('documentArchiveModal').classList.add('hidden');document.querySelector('.step .stepno')?.closest('.card');$('generate').scrollIntoView({behavior:'smooth',block:'center'});toast(missing.length?`Arxiv formaya qaytarıldı. Registrdə olmayan qaimələr: ${missing.join(', ')}`:'Arxiv formaya qaytarıldı — qaiməni/şablonu düzəldib yenidən yarada bilərsiniz.')}
$('closeDocumentFiles').onclick=()=>$('documentFilesModal').classList.add('hidden');$('manageDocumentArchive').onclick=()=>{$('documentArchiveModal').classList.remove('hidden');renderDocumentArchive()};$('closeDocumentArchive').onclick=()=>$('documentArchiveModal').classList.add('hidden');$('documentArchiveSearch').oninput=renderDocumentArchive;$('refreshDocumentArchive').onclick=loadDocumentArchive;$('openLastDocumentFolder').onclick=()=>{const id=state.lastResult?.archiveId||state.documentArchives[0]?.id;if(!id)return toast('Arxivdə alt sənəd paketi yoxdur.');openArchiveFolder(id)};

// Templates
$('templateEntityType').addEventListener('change',()=>{updateTemplateLinks();updateTemplateStatuses()});function currentTemplateEntity(){return $('templateEntityType').value}
function updateTemplateLinks(){const e=currentTemplateEntity();document.querySelectorAll('.templateDownload').forEach(a=>a.href=`/api/templates/${a.dataset.type}?entityType=${e}`);document.querySelectorAll('.activeTemplateDownload').forEach(a=>a.onclick=async ev=>{ev.preventDefault();try{await downloadWithWorkspace(`/api/templates/${a.dataset.type}/active?entityType=${e}`,`${a.dataset.type}_${e.toLowerCase()}_aktiv_sablon.xlsx`)}catch(err){toast(err.message)}})}
function updateTemplateStatuses(){const e=currentTemplateEntity();for(const t of ['hf','qr','tt']){const status=$(`${t}TemplateStatus`),pill=document.querySelector(`[data-state="${t}"]`);if(status)status.textContent=`${entityLabel(e)} üçün vahid faktiki standart şablon istifadə olunur.`;if(pill){pill.textContent='Faktiki standart';pill.classList.remove('custom')}}if($('templateWorkspaceStatus'))$('templateWorkspaceStatus').textContent=`${entityLabel(e)} · STANDARD_ONLY · bütün kompüterlərdə eyni faktiki şablon.`}
function validateTemplateFile(file){if(!file)throw new Error('Şablon faylı seçilməyib.');if(!/\.xlsx$/i.test(file.name||''))throw new Error('Şablon yalnız .xlsx formatında olmalıdır.');if(file.size>12*1024*1024)throw new Error('Şablon faylı 12 MB-dan böyük ola bilməz.')}
async function uploadTemplate(type,file){try{validateTemplateFile(file);const e=currentTemplateEntity(),fd=new FormData();fd.append('file',file);const card=document.querySelector(`[data-card="${type}"]`);card?.classList.add('is-loading');if($('templateWorkspaceStatus'))$('templateWorkspaceStatus').textContent=`${file.name} yoxlanılır və ${entityLabel(e)} üçün aktivləşdirilir...`;const d=await api(`/api/templates/upload/${type}?entityType=${e}`,{method:'POST',body:fd});state.activeTemplates[activeKey(e,type)]=d.uploadId;updateTemplateStatuses();toast(`${type.toUpperCase()} · ${entityLabel(e)} üçün yeni aktiv şablon yükləndi.`)}catch(err){toast(err.message);if($('templateWorkspaceStatus'))$('templateWorkspaceStatus').textContent=err.message}finally{document.querySelector(`[data-card="${type}"]`)?.classList.remove('is-loading');const input=$(`${type}TemplateFile`);if(input)input.value=''}}
for(const zone of document.querySelectorAll('.dropzone')){const type=zone.dataset.drop,input=$(`${type}TemplateFile`);zone.onclick=()=>input.click();input.onchange=()=>uploadTemplate(type,input.files[0]);['dragenter','dragover'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.add('drag')}));['dragleave','drop'].forEach(ev=>zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.remove('drag')}));zone.addEventListener('drop',e=>uploadTemplate(type,e.dataTransfer.files[0]))}
for(const b of document.querySelectorAll('.templateResetBtn'))b.onclick=async()=>{const e=currentTemplateEntity(),t=b.dataset.type;if(!confirm(`${entityLabel(e)} üçün ${t.toUpperCase()} şablonu faktiki standarta qaytarılsın? Xüsusi aktiv fayl və xəritələndirmə sıfırlanacaq.`))return;try{await api(`/api/templates/${t}/reset?entityType=${e}`,{method:'POST'});delete state.activeTemplates[activeKey(e,t)];delete state.templateMappings[activeKey(e,t)];updateTemplateStatuses();toast(`${t.toUpperCase()} · ${entityLabel(e)} standart şablona qaytarıldı.`)}catch(err){toast(err.message)}};
for(const b of document.querySelectorAll('.templateEditorBtn'))b.onclick=()=>openTemplateEditor(b.dataset.type);
function templateEditorDirty(flag=true){state.editor.dirty=flag;if($('templateEditorStatus'))$('templateEditorStatus').textContent=flag?'Yadda saxlanmamış dəyişiklik var.':'Dəyişikliklər yadda saxlanılıb.'}
function closeTemplateEditor(){if(state.editor.dirty&&!confirm('Yadda saxlanmamış şablon dəyişiklikləri var. Redaktoru bağlamaq istəyirsiniz?'))return;$('templateModal').classList.add('hidden')}
$('closeEditor').onclick=closeTemplateEditor;
function renderFieldPalette(){const q=normalize($('fieldSearch')?.value),items=Object.entries(state.editor.fields).filter(([k,v])=>!q||normalize(k).includes(q)||normalize(v).includes(q));$('fieldPalette').innerHTML=items.map(([k,v])=>`<button type="button" class="field-token ${state.editor.selectedField===k?'selected':''}" draggable="true" data-field="${esc(k)}"><span>${esc(v)}</span><small>${esc(k)}</small></button>`).join('');document.querySelectorAll('.field-token').forEach(x=>{x.ondragstart=e=>{state.editor.selectedField=x.dataset.field;e.dataTransfer.setData('text/template-field',x.dataset.field)};x.onclick=()=>{state.editor.selectedField=state.editor.selectedField===x.dataset.field?null:x.dataset.field;renderFieldPalette();if($('templateEditorStatus'))$('templateEditorStatus').textContent=state.editor.selectedField?'İndi yerləşdirmək istədiyiniz Excel hüceyrəsinə klik edin.':'Dinamik sahə seçimi ləğv edildi.'}})}
async function openTemplateEditor(type){const entity=currentTemplateEntity(),uploadId=state.activeTemplates[activeKey(entity,type)]||'';try{const d=await api(`/api/templates/${type}/editor?entityType=${entity}&uploadId=${encodeURIComponent(uploadId)}`);state.editor={type,entity,uploadId:d.activeUploadId||uploadId,mapping:{...(d.mapping||{})},originalMapping:{...(d.mapping||{})},fields:d.fields||{},originalCells:new Map(),selectedCell:null,selectedField:null,rows:d.rows||[],dirty:false};state.templateMappings[activeKey(entity,type)]={...(d.mapping||{})};$('editorTitle').textContent=`${type.toUpperCase()} — ${entityLabel(entity)} şablon redaktoru`;$('fieldSearch').value='';renderFieldPalette();renderSheetEditor(d.rows||[]);$('templateModal').classList.remove('hidden');if($('templateEditorStatus'))$('templateEditorStatus').textContent='Mətni hüceyrədə dəyişin və ya dinamik sahələri yerləşdirin. Yadda saxlamadan dəyişiklik aktiv olmayacaq.'}catch(e){toast(e.message)}}
function selectSheetCell(cell){document.querySelectorAll('.sheet-cell.selected').forEach(x=>x.classList.remove('selected'));state.editor.selectedCell=cell?.dataset.ref||null;if(cell){cell.classList.add('selected');$('selectedCellLabel').textContent=`Seçilmiş hüceyrə: ${cell.dataset.ref}`;if(state.editor.selectedField){state.editor.mapping[state.editor.selectedField]=cell.dataset.ref;state.editor.selectedField=null;templateEditorDirty(true);renderFieldPalette();refreshMappingBadges()}}else $('selectedCellLabel').textContent='Hüceyrə seçilməyib'}
function renderSheetEditor(rows){const reverse={};for(const[k,v]of Object.entries(state.editor.mapping))reverse[v]=(reverse[v]||[]).concat(k);const cols=Math.max(1,...rows.map(r=>r.length));$('sheetEditor').style.setProperty('--sheet-cols',cols);$('sheetEditorSize').textContent=`${rows.length} sətir · ${cols} sütun`;$('sheetEditor').innerHTML=rows.map((row,ri)=>`<div class="sheet-row" style="--sheet-cols:${cols}"><div class="row-head">${ri+1}</div>${row.map(c=>{state.editor.originalCells.set(c.ref,c.value||'');const badges=(reverse[c.ref]||[]).map(k=>mappingBadgeHtml(k)).join('');return `<div class="sheet-cell" data-ref="${c.ref}"><div class="cell-ref">${c.ref}</div><div class="cell-value" contenteditable="true" spellcheck="false">${esc(c.value||'')}</div><div class="cell-mappings">${badges}</div></div>`}).join('')}</div>`).join('');document.querySelectorAll('.sheet-cell').forEach(cell=>{cell.onclick=e=>{if(e.target.closest('.mapping-remove'))return;selectSheetCell(cell)};cell.ondragover=e=>{e.preventDefault();cell.classList.add('drop-target')};cell.ondragleave=()=>cell.classList.remove('drop-target');cell.ondrop=e=>{e.preventDefault();cell.classList.remove('drop-target');const field=e.dataTransfer.getData('text/template-field');if(field){state.editor.mapping[field]=cell.dataset.ref;state.editor.selectedField=null;templateEditorDirty(true);renderFieldPalette();refreshMappingBadges()}};cell.querySelector('.cell-value')?.addEventListener('input',()=>templateEditorDirty(true))});document.querySelectorAll('.mapping-remove').forEach(bindBadge);selectSheetCell(null)}
function mappingBadgeHtml(k){return `<span class="mapping-badge" data-field="${esc(k)}"><span>${esc(state.editor.fields[k]||k)}</span><button type="button" class="mapping-remove" data-field="${esc(k)}" title="Bu dinamik sahəni sil">×</button></span>`}
function bindBadge(b){b.onclick=e=>{e.stopPropagation();delete state.editor.mapping[b.dataset.field];templateEditorDirty(true);refreshMappingBadges()}}
function refreshMappingBadges(){document.querySelectorAll('.cell-mappings').forEach(x=>x.innerHTML='');for(const[k,ref]of Object.entries(state.editor.mapping)){const cell=document.querySelector(`.sheet-cell[data-ref="${CSS.escape(ref)}"] .cell-mappings`);if(cell)cell.insertAdjacentHTML('beforeend',mappingBadgeHtml(k))}document.querySelectorAll('.mapping-remove').forEach(bindBadge)}
$('fieldSearch').oninput=renderFieldPalette;
$('clearSelectedCell').onclick=()=>{if(!state.editor.selectedCell)return toast('Əvvəlcə Excel görünüşündə bir hüceyrə seçin.');const cell=document.querySelector(`.sheet-cell[data-ref="${CSS.escape(state.editor.selectedCell)}"] .cell-value`);if(cell){cell.innerText='';templateEditorDirty(true);cell.focus()}};
$('undoTemplateEdits').onclick=()=>{if(!state.editor.type)return;document.querySelectorAll('.sheet-cell').forEach(c=>{const v=c.querySelector('.cell-value');if(v)v.innerText=state.editor.originalCells.get(c.dataset.ref)||''});state.editor.mapping={...state.editor.originalMapping};state.editor.selectedField=null;refreshMappingBadges();renderFieldPalette();templateEditorDirty(false);toast('Cari, hələ yadda saxlanmamış düzəlişlər ləğv edildi.')};
$('downloadEditorTemplate').onclick=async()=>{const {type,entity}=state.editor;if(!type)return;try{await downloadWithWorkspace(`/api/templates/${type}/active?entityType=${entity}`,`${type}_${entity.toLowerCase()}_excelde_redakte.xlsx`)}catch(e){toast(e.message)}};
