$('saveTemplateEditor').onclick=async()=>{const {type,entity}=state.editor;if(!type)return;const edits={};document.querySelectorAll('.sheet-cell').forEach(c=>{const ref=c.dataset.ref,val=c.querySelector('.cell-value').innerText,old=state.editor.originalCells.get(ref)||'';if(val!==old)edits[ref]=val});try{$('saveTemplateEditor').disabled=true;$('saveTemplateEditor').textContent='Yadda saxlanır...';if(Object.keys(edits).length){const d=await api(`/api/templates/${type}/cell-edits?entityType=${entity}&uploadId=${encodeURIComponent(state.editor.uploadId||'')}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(edits)});state.editor.uploadId=d.uploadId;state.activeTemplates[activeKey(entity,type)]=d.uploadId}const mappingSaved=await api(`/api/templates/${type}/mapping?entityType=${entity}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.editor.mapping)});state.templateMappings[activeKey(entity,type)]={...(mappingSaved.mapping||{})};document.querySelectorAll('.sheet-cell').forEach(c=>state.editor.originalCells.set(c.dataset.ref,c.querySelector('.cell-value').innerText));state.editor.originalMapping={...state.editor.mapping};state.editor.dirty=false;updateTemplateStatuses();if($('templateEditorStatus'))$('templateEditorStatus').textContent='Dəyişikliklər yadda saxlandı və aktiv şablona tətbiq edildi.';toast('Şablon dəyişiklikləri yadda saxlandı və aktiv edildi.')}catch(e){toast(e.message)}finally{$('saveTemplateEditor').disabled=false;$('saveTemplateEditor').textContent='Dəyişiklikləri yadda saxla və aktiv et'}};


// EFP Qaimə Paketləmə / eFP hazırlıq registri
function outgoingStatusClass(status){return normalize(status)==='packaged'?'packaged':'draft'}
function outgoingStats(){
  const all=state.outgoingInvoices.length;
  const packaged=state.outgoingInvoices.filter(x=>normalize(x.status)==='packaged').length;
  const draft=all-packaged;
  const total=state.outgoingInvoices.reduce((sum,x)=>sum+Number(x.total||0),0);
  if($('outStatAll'))$('outStatAll').textContent=all.toLocaleString('az-AZ');
  if($('outStatDraft'))$('outStatDraft').textContent=draft.toLocaleString('az-AZ');
  if($('outStatPackaged'))$('outStatPackaged').textContent=packaged.toLocaleString('az-AZ');
  if($('outStatTotal'))$('outStatTotal').textContent=money(total);
}
async function loadOutgoing(){try{const d=await api('/api/outgoing');state.outgoingInvoices=d.invoices||[];for(const id of [...state.outgoingSelected])if(!state.outgoingInvoices.some(x=>x.id===id))state.outgoingSelected.delete(id);outgoingStats();renderOutgoingList();$('outgoingStatus').textContent=state.outgoingInvoices.length?`Şəxsi EFP registrində ${state.outgoingInvoices.length} qaimə var. Yeni qaimə yarada, Excel-dən import edə və ya registri aça bilərsiniz.`:'EFP qaimə registri boşdur. İlk qaiməni yaradın və ya Excel-dən import edin.'}catch(e){$('outgoingStatus').textContent=e.message}}
