$('uploadOutgoing').onclick=async()=>{const file=$('outgoingFile').files[0];if(!file)return toast('Göndərilən qaimə Excel-i seçilməyib.');const fd=new FormData();fd.append('file',file);try{$('uploadOutgoing').disabled=true;$('uploadOutgoing').textContent='Import edilir...';$('outgoingStatus').textContent='Excel yoxlanılır, registrdə olmayan qaimələr müəyyən edilir...';const d=await api('/api/outgoing/upload',{method:'POST',body:fd});await loadOutgoing();$('outgoingStatus').textContent=d.cached?`${file.name}: bu Excel əvvəl import edilib — mövcud registr dərhal göstərildi.`:`${file.name}: ${d.parsed||0} qaimə oxundu · ${d.added||0} yeni əlavə edildi · ${d.skipped||0} təkrar atlandı.`;toast(d.cached?'Bu Excel artıq registrdədir.':`${d.added||0} yeni göndərilən qaimə əlavə edildi.`)}catch(e){toast(e.message);$('outgoingStatus').textContent=e.message}finally{$('uploadOutgoing').disabled=false;$('uploadOutgoing').textContent='Seçilmiş Excel-i import et'}};
function renderOutgoingList(){
  if(!$('outgoingListBody'))return;
  const q=normalize($('outgoingSearch')?.value);
  const list=state.outgoingInvoices.filter(x=>!q||[x.invoiceNumber,x.buyerName,x.buyerVoen,x.sellerName,x.sellerVoen,x.status].some(v=>normalize(v).includes(q)));
  $('outgoingListBody').innerHTML=list.map(x=>`<tr class="${state.outgoingSelected.has(x.id)?'selected-row':''}"><td><input class="out-check" type="checkbox" data-id="${esc(x.id)}" ${state.outgoingSelected.has(x.id)?'checked':''}></td><td><b>${esc(x.invoiceNumber||'')}</b><small>${x.manual?'Əl ilə yaradılıb':'Excel import'}</small></td><td>${esc(x.invoiceDate||'')}</td><td><b>${esc(x.buyerName||x.buyerVoen||'—')}</b><small>${x.buyerName?esc(x.buyerVoen||''):''}</small></td><td><b>${esc(x.sellerName||x.sellerVoen||'—')}</b><small>${x.sellerName?esc(x.sellerVoen||''):''}</small></td><td><b>${money(x.total)}</b><small>${(x.items?.length||0)} sətir</small></td><td><span class="out-status-pill ${outgoingStatusClass(x.status)}">${normalize(x.status)==='packaged'?'Paketlənib':'Hazırlanır'}</span></td><td><button class="mini out-edit" data-id="${esc(x.id)}">Düzəliş</button> <button class="mini danger out-delete" data-id="${esc(x.id)}">Sil</button></td></tr>`).join('');
  document.querySelectorAll('.out-check').forEach(ch=>ch.onchange=()=>{ch.checked?state.outgoingSelected.add(ch.dataset.id):state.outgoingSelected.delete(ch.dataset.id);renderOutgoingList()});
  document.querySelectorAll('.out-edit').forEach(b=>b.onclick=()=>openOutgoingEditor(b.dataset.id));
  document.querySelectorAll('.out-delete').forEach(b=>b.onclick=()=>deleteOutgoing(b.dataset.id));
  if($('outgoingSelectedInfo'))$('outgoingSelectedInfo').textContent=`${state.outgoingSelected.size} qaimə seçilib`;
  if($('outgoingRegistryInfo'))$('outgoingRegistryInfo').textContent=`Göstərilir: ${list.length} / ${state.outgoingInvoices.length}`;
  $('outgoingEmptyState')?.classList.toggle('hidden',state.outgoingInvoices.length!==0||!!q);
  if($('outgoingListBody'))$('outgoingListBody').closest('.tablewrap')?.classList.toggle('hidden',state.outgoingInvoices.length===0&&!q);
}
function outgoingCompanyOptions(roleHint='',query=''){
  const q=normalize(query);
  const list=[...state.companies].filter(c=>!q||normalize(`${c.company||''} ${c.voen||''} ${c.role||''}`).includes(q)).sort((a,b)=>Number(normalize(b.role).includes(roleHint))-Number(normalize(a.role).includes(roleHint))||(a.company||'').localeCompare(b.company||'','az'));
  return '<option value="">— Bazadan seç —</option>'+list.map(c=>`<option value="${esc(c.id)}">${esc(c.company||'')} · ${esc(c.voen||'VÖEN yoxdur')} ${normalize(c.role).includes(roleHint)?'· uyğun rol':''}</option>`).join('');
}
function fillOutgoingCompanySelectors(){
  const buyerCurrent=$('outBuyerCompanySelect')?.value||'',sellerCurrent=$('outSellerCompanySelect')?.value||'';
  $('outBuyerCompanySelect').innerHTML=outgoingCompanyOptions('sifarisci',$('outBuyerCompanyFilter')?.value||'');
  $('outSellerCompanySelect').innerHTML=outgoingCompanyOptions('icraci',$('outSellerCompanyFilter')?.value||'');
  if([...$('outBuyerCompanySelect').options].some(o=>o.value===buyerCurrent))$('outBuyerCompanySelect').value=buyerCurrent;
  if([...$('outSellerCompanySelect').options].some(o=>o.value===sellerCurrent))$('outSellerCompanySelect').value=sellerCurrent;
}
function findCompanyForOutgoing(name,voen){const v=String(voen||'').replace(/\D/g,'');return state.companies.find(c=>v&&String(c.voen||'').replace(/\D/g,'')===v)||state.companies.find(c=>normalize(c.company)===normalize(name))||null}
function resolveOutgoingPartyFromVoen(side){
  const voen=$(side==='buyer'?'outBuyerVoen':'outSellerVoen').value;
  const c=findCompanyForOutgoing('',voen),nameId=side==='buyer'?'outBuyerName':'outSellerName',selectId=side==='buyer'?'outBuyerCompanySelect':'outSellerCompanySelect';
  if(c){$(nameId).value=c.company||'';if([...$(selectId).options].some(o=>o.value===c.id))$(selectId).value=c.id}
  else {$(selectId).value='';}
}
function selectOutgoingCompany(side,id){
  const c=companyById(id);if(!c)return;
  if(side==='buyer'){$('outBuyerVoen').value=c.voen||'';$('outBuyerName').value=c.company||'';if(c.contractNo&&!$('outBasis').value)$('outBasis').value=c.contractNo}
  else {$('outSellerVoen').value=c.voen||'';$('outSellerName').value=c.company||''}
  syncOutgoingMetaMirrors();updateOutgoingSummary(false)
}
$('outBuyerCompanyFilter').oninput=fillOutgoingCompanySelectors;
$('outSellerCompanyFilter').oninput=fillOutgoingCompanySelectors;
$('outBuyerCompanySelect').onchange=()=>selectOutgoingCompany('buyer',$('outBuyerCompanySelect').value);
$('outSellerCompanySelect').onchange=()=>selectOutgoingCompany('seller',$('outSellerCompanySelect').value);
