async function resumeEtxTask(){const saved=localStorage.getItem('taxdata_agent_etx_task');etxPendingTin=localStorage.getItem('taxdata_agent_etx_tin')||'';if(!saved)return;const d=await probeAgent();if(!agentIsFullyReady(d))return;try{const st=await agentApi(`/tasks/${encodeURIComponent(saved)}`,{timeout:2500});if(st?.taskId){etxTaskId=saved;renderEtxStatus(st);if(!['COMPLETED','FAILED','CANCELLED'].includes(st.status)){if(etxPollTimer)clearInterval(etxPollTimer);etxPollTimer=setInterval(pollEtxStatus,900)}}}catch{localStorage.removeItem('taxdata_agent_etx_task')}}
const etxType=()=>document.querySelector('input[name="etxType"]:checked')?.value||'received';
function etxSetRunning(running){$('etxStartBtn').disabled=running;$('etxStartBtn').textContent=running?'e-Taxes-dən gətirilir...':'e-Taxes-dən gətirməyə başla';$('etxCancelBtn').classList.toggle('hidden',!running)}
function etxPhaseLabel(x){return ({LOGIN:'Giriş',LOGIN_FORM:'Giriş forması',OTP:'OTP təsdiqi',TIN:'VÖEN seçimi',SESSION:'Sessiya',LIST:'Qaimə siyahısı',DETAILS:'Qaimə detalları',EXCEL:'Excel hazırlanır',IMPORT:'Registrə əlavə',Hazırdır:'Hazırdır',Xəta:'Xəta',Dayandırıldı:'Dayandırıldı'})[x]||x||'Hazırdır'}
function renderEtxStatus(d){
  if(!d)return;etxLastStatus=d;const progress=Math.max(0,Math.min(100,Number(d.progress||0)));
  $('etxPhase').textContent=etxPhaseLabel(d.phase);$('etxPercent').textContent=progress+'%';$('etxProgressBar').style.width=progress+'%';$('etxStatus').textContent=d.message||'';
  $('etxStats').innerHTML=`<span><b>${num(d.invoiceCount||0)}</b><small>qaimə</small></span><span><b>${num(d.processedInvoices||0)}</b><small>emal</small></span><span><b>${num(d.rowCount||0)}</b><small>sətir</small></span>`;
  $('etxLogs').textContent=(d.logs&&d.logs.length)?d.logs.join('\n'):'Hələ log yoxdur.';
  const terminal=['COMPLETED','FAILED','CANCELLED'].includes(d.status);etxSetRunning(!terminal);const ready=d.status==='COMPLETED'&&d.downloadReady;$('etxResult').classList.toggle('hidden',!ready);
  if(ready)$('etxImportResult').textContent=d.importIntoRegistry?'Excel hazırdır; registrə əlavə tamamlanır...':'Excel lokal kompüterdə hazırlandı.';
  if(terminal&&etxPollTimer){clearInterval(etxPollTimer);etxPollTimer=null}if(terminal&&etxCompletionHandled!==d.taskId){etxCompletionHandled=d.taskId;handleEtxCompletion(d).catch(e=>{console.warn(e);toast(e.message)})}
}
async function pollEtxStatus(){if(!etxTaskId)return;try{const d=await agentApi(`/tasks/${encodeURIComponent(etxTaskId)}`,{timeout:5000});renderEtxStatus(d)}catch(e){if(etxPollTimer){clearInterval(etxPollTimer);etxPollTimer=null}etxSetRunning(false);$('etxStatus').textContent=e.message;toast(e.message)}}
async function getAgentExcelBlob(taskId){if(etxLastBlob)return etxLastBlob;const r=await agentFetch(`/tasks/${encodeURIComponent(taskId)}/download`,{timeout:30000});etxLastBlob=await r.blob();return etxLastBlob}
async function importAgentExcel(d){const blob=await getAgentExcelBlob(d.taskId);const fd=new FormData();fd.append('file',blob,d.fileName||'e-taxes_qaimeler.xlsx');const ir=await api('/api/invoices/upload',{method:'POST',body:fd});d.importedCount=ir.added||0;d.skippedCount=ir.skipped||0;await loadInvoices();scheduleLocalSnapshot('e-Taxes qaimələri registrə əlavə edildi');return ir}
async function handleEtxCompletion(d){
  localStorage.removeItem('taxdata_agent_etx_task');localStorage.removeItem('taxdata_agent_etx_tin');
  if(d.status==='COMPLETED'){
    {try{const me=await api('/api/auth/me');if(me?.user){currentUser=me.user;applyEtaxesProfile();await LocalWorkspaceStore.syncUserProfile(currentUser)}}catch{}}
    if(d.importIntoRegistry&&d.downloadReady){const ir=await importAgentExcel(d);$('etxImportResult').textContent=`${num(ir.added||0)} yeni qaimə şəxsi registrə əlavə edildi · ${num(ir.skipped||0)} təkrar atlandı.`}
    else $('etxImportResult').textContent='Excel istifadəçinin kompüterində Downloads\\TaxData\\eTaxes qovluğunda hazırdır.';
    toast(d.message||'e-Taxes Excel-i hazırdır.');
  }else if(d.status==='FAILED'){toast('e-Taxes xətası: '+(d.message||'naməlum xəta'))}else if(d.status==='CANCELLED'){toast('e-Taxes gətirmə prosesi dayandırıldı.')}
}
$('etxStartBtn').onclick=async()=>{
  const phone=$('etxPhone').value.trim(),userId=$('etxUserId').value.trim(),tin=$('etxTin').value.replace(/\D/g,''),contragentTin=$('etxContragent').value.replace(/\D/g,'');
  if(phone.replace(/\D/g,'').length<9)return toast('ASAN İmza telefon nömrəsini düzgün yazın.');if(!userId)return toast('İstifadəçi ID-ni yazın.');if(tin.length!==10)return toast('VÖEN 10 rəqəm olmalıdır.');if(contragentTin&&contragentTin.length!==10)return toast('Kontragent VÖEN 10 rəqəm olmalıdır.');if(currentUser?.role!=='ADMIN'&&currentUser?.etaxesTin&&tin!==String(currentUser.etaxesTin).replace(/\D/g,''))return toast(`Bu hesab e‑Taxes üçün ${currentUser.etaxesTin} VÖEN-inə bağlıdır.`);
  const agent=await probeAgent();if(!agentIsFullyReady(agent)){openAgentInstallModal(agent?`Agent tam deyil: ${agentMissingLabel(agent)}. Bərpa edin.`:'Lokal agent tapılmadı. Quraşdırma/bərpa faylını yenidən endirin.',true);return}
  const b=agent.browser||{};if(b.error){toast(b.error);return}
  const body={phoneNumber:phone,userId,tin,contragentTin,invoiceType:etxType(),startDate:$('etxStart').value||null,endDate:$('etxEnd').value||null,concurrencyLimit:Number($('etxConcurrency').value||20),importIntoRegistry:$('etxImport').checked};
  try{
    etxSetRunning(true);etxLastBlob=null;etxPendingTin=tin;$('etxResult').classList.add('hidden');$('etxStatus').textContent='Lokal agent üçün yeni server icazəsi hazırlanır...';$('etxLogs').textContent='Başlanır...';etxCompletionHandled='';
    let d=null,lastErr=null;
    for(let attempt=1;attempt<=2;attempt++){
      const grant=await api('/api/etaxes-export/grant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tin,phone,userId})});body.agentGrant=grant.grant;
      try{d=await agentApi('/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),timeout:10000});break}catch(err){lastErr=err;if(attempt===1&&/icazəsi|icazəsi|grant|vaxtı bitib/i.test(err.message||'')){$('etxStatus').textContent='Lokal agent icazəsi yenilənir və ikinci dəfə yoxlanır...';continue}throw err}
    }
    if(!d)throw lastErr||new Error('Lokal agent üçün server icazəsi yaradıla bilmədi.');
    etxTaskId=d.taskId;localStorage.setItem('taxdata_agent_etx_task',etxTaskId);localStorage.setItem('taxdata_agent_etx_tin',tin);renderEtxStatus(d);if(etxPollTimer)clearInterval(etxPollTimer);etxPollTimer=setInterval(pollEtxStatus,700);setTimeout(pollEtxStatus,120)
  }catch(e){etxSetRunning(false);$('etxStatus').textContent=e.message;toast(e.message)}
};
$('etxCancelBtn').onclick=async()=>{if(!etxTaskId)return;try{await agentApi(`/tasks/${encodeURIComponent(etxTaskId)}/cancel`,{method:'POST'});$('etxStatus').textContent='Dayandırma sorğusu lokal agentə göndərildi...'}catch(e){toast(e.message)}};
$('etxDownload').onclick=async()=>{if(!etxLastStatus?.taskId)return;try{const blob=await getAgentExcelBlob(etxLastStatus.taskId),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=etxLastStatus.fileName||'e-taxes_qaimeler.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}catch(e){toast(e.message)}};
$('etxSaveLocal').onclick=async()=>{if(!etxLastStatus?.downloadReady)return;toast('Agent Excel-i artıq bu kompüterdə Downloads\\TaxData\\eTaxes qovluğuna yazıb.')};
$('etxOpenInvoices').onclick=async()=>{try{await loadInvoices();$('invoiceListModal').classList.remove('hidden');renderInvoiceList()}catch(e){toast(e.message)}};

// Müqavilə arxivi
async function loadContracts(){try{const d=await api('/api/contracts');state.contracts=d.contracts||[];$('contractStatus').textContent=`${state.contracts.length} müqavilə lokal workspace arxivindədir.`;$('contractFolderInfo').textContent='Müqavilələr lokal backup-da saxlanılır; seçilmiş kompüter qovluğuna ayrıca yaza bilərsiniz.';renderContractList()}catch(e){$('contractStatus').textContent=e.message}}
function fillContractCompanySelects(){const opts='<option value="">Tərəfi seç</option>'+state.companies.map(c=>`<option value="${esc(c.id)}">${esc(c.company)} · ${esc(c.voen||'')}</option>`).join('');$('contractExecutor').innerHTML=opts;$('contractCustomer').innerHTML=opts}
$('newContract').onclick=()=>openContractEditor();$('newContractFromList').onclick=()=>openContractEditor();$('openContractFolder').onclick=async()=>{try{const h=await LocalWorkspaceStore.chooseDirectory(currentUser.id);await refreshLocalStorageInfo();toast(`Lokal qovluq seçildi: ${h.name}. Müqavilələr yaradıldıqca TaxData_Muqavileler alt qovluğuna yazılacaq.`)}catch(e){toast(e.message)}};$('createContractForOrderer')?.addEventListener('click',()=>openContractEditor('',$('ordererCompany').value));const openContractsUi=()=>{$('contractModal').classList.remove('hidden');renderContractList()};$('openContractsQuick')?.addEventListener('click',openContractsUi);$('manageContracts').onclick=openContractsUi;$('closeContracts').onclick=()=>$('contractModal').classList.add('hidden');$('closeContractEdit').onclick=()=>$('contractEditModal').classList.add('hidden');$('contractSearch').oninput=renderContractList;
function openContractEditor(recordId='',customerId=''){fillContractCompanySelects();const r=recordId?state.contracts.find(x=>x.id===recordId):null;const ex=r?.executorCompanyId||$('executorCompany').value||state.companies.find(c=>(c.role||'').toUpperCase().includes('İCRA'))?.id||'';const cu=r?.customerCompanyId||customerId||$('ordererCompany').value||'';$('contractEditId').value=r?.id||'';$('contractExecutor').value=ex;$('contractCustomer').value=cu;$('contractEditNo').value=r?.contractNo||companyById(cu)?.contractNo||'';$('contractEditDate').value=r?.contractDate||companyById(cu)?.contractDate||new Date().toLocaleDateString('az-AZ');$('contractEditModal').classList.remove('hidden')}
$('saveContract').onclick=async()=>{const body={id:$('contractEditId').value||null,executorCompanyId:$('contractExecutor').value,customerCompanyId:$('contractCustomer').value,contractNo:$('contractEditNo').value.trim(),contractDate:$('contractEditDate').value.trim()};if(!body.executorCompanyId||!body.customerCompanyId)return toast('Şirkət və müştəri seçilməlidir.');try{$('saveContract').disabled=true;const r=await api('/api/contracts/create',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('contractEditModal').classList.add('hidden');await Promise.all([loadCompanies(),loadContracts()]);const saved=await autoSaveRemoteFile(`/api/contracts/${encodeURIComponent(r.id)}/download`,r.fileName||`${r.contractNo||'muqavile'}.docx`,'TaxData_Muqavileler');toast(`${r.contractNo||'Müqavilə'} Word olaraq yaradıldı.${saved?' Lokal qovluğa da yazıldı.':''}`)}catch(e){toast(e.message)}finally{$('saveContract').disabled=false}};
function renderContractList(){if(!$('contractListBody'))return;const q=normalize($('contractSearch')?.value);const list=state.contracts.filter(r=>!q||[r.contractNo,r.contractDate,r.customerName,r.executorName,r.fileName].some(v=>normalize(v).includes(q)));$('contractListBody').innerHTML=list.map(r=>`<tr><td><b>${esc(r.contractNo||'')}</b></td><td>${esc(r.contractDate||'')}</td><td>${esc(r.customerName||'')}</td><td title="${esc(r.relativePath||'')}">${esc(r.fileName||'')}</td><td><button class="mini ctr-preview" data-id="${esc(r.id)}">Bax</button> <button class="mini ctr-print" data-id="${esc(r.id)}">2 nüsxə çap</button> <button class="mini ctr-openword" data-id="${esc(r.id)}">Lokal qovluğa yaz</button> <button class="mini ctr-download" data-id="${esc(r.id)}">Word endir</button>${r.customerCompanyId?` <button class="mini ctr-edit" data-id="${esc(r.id)}">Redaktə</button>`:''} <button class="mini danger ctr-delete" data-id="${esc(r.id)}">Sil</button></td></tr>`).join('');document.querySelectorAll('.ctr-preview').forEach(b=>b.onclick=async()=>{try{await api('/api/workspace/state');window.open(`/api/contracts/${encodeURIComponent(b.dataset.id)}/preview`,'_blank','noopener')}catch(e){toast(e.message)}});document.querySelectorAll('.ctr-print').forEach(b=>b.onclick=async()=>{try{await api('/api/workspace/state');window.open(`/api/contracts/${encodeURIComponent(b.dataset.id)}/print?copies=2`,'_blank','noopener')}catch(e){toast(e.message)}});document.querySelectorAll('.ctr-openword').forEach(b=>b.onclick=async()=>{try{const r=state.contracts.find(x=>x.id===b.dataset.id);const info=await LocalWorkspaceStore.info(currentUser.id);if(!info.hasFolder)await LocalWorkspaceStore.chooseDirectory(currentUser.id);await LocalWorkspaceStore.saveUrl(currentUser.id,`/api/contracts/${encodeURIComponent(b.dataset.id)}/download`,r?.fileName||'muqavile.docx','TaxData_Muqavileler');toast('Word müqavilə bu kompüterdə seçilmiş lokal qovluğa yazıldı.')}catch(e){toast(e.message)}});document.querySelectorAll('.ctr-download').forEach(b=>b.onclick=async()=>{try{const r=state.contracts.find(x=>x.id===b.dataset.id);await downloadWithWorkspace(`/api/contracts/${encodeURIComponent(b.dataset.id)}/download`,r?.fileName||'muqavile.docx')}catch(e){toast(e.message)}});document.querySelectorAll('.ctr-edit').forEach(b=>b.onclick=()=>openContractEditor(b.dataset.id));document.querySelectorAll('.ctr-delete').forEach(b=>b.onclick=()=>deleteContract(b.dataset.id))}
async function deleteContract(id){if(!confirm('Müqavilə arxivdən və Word faylı ilə birlikdə silinsin?'))return;try{await api(`/api/contracts/${encodeURIComponent(id)}?deleteFile=true`,{method:'DELETE'});await loadContracts();toast('Müqavilə silindi.')}catch(e){toast(e.message)}}
$('activeContractTemplate')?.addEventListener('click',async e=>{e.preventDefault();try{await downloadWithWorkspace('/api/contracts/template','muqavile_faktiki_standart.docx')}catch(err){toast(err.message)}});
$('importContractWord').onclick=async()=>{const file=$('contractArchiveFile').files[0];if(!file)return toast('Arxivə əlavə ediləcək Word faylı seçilməyib.');const fd=new FormData();fd.append('file',file);try{await api('/api/contracts/import',{method:'POST',body:fd});await loadContracts();toast('Word müqavilə arxivə əlavə edildi.')}catch(e){toast(e.message)}};


